update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Alaska has no statewide residential building code for one- to three-family homes. The State Fire Marshal enforces the 2021 IBC, IEBC, IMC, IFGC (partial) and IFC for commercial and larger residential buildings, deferring to qualified municipalities. The state electrical (2020 NEC) and plumbing (2018 UPC) codes are statewide minimums. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'AK' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Alabama has no statewide building code for most private construction: cities and counties adopt and enforce their own codes. The state''s building code covers only state projects, schools, hotels/motels and theaters, and a new state residential code (adopted by the Home Builders Licensure Board) is to be enforced by local jurisdictions that have permitting and inspection programs. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'AL' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Arkansas Fire Prevention Code (2021; Volume I Fire, Volume II Building, Volume III Residential) is the statewide code issued by the State Fire Marshal, with building enforcement mostly done by local governments. Plumbing, fuel gas, mechanical and electrical codes are adopted by separate state boards. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'AR' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'awaiting_verification', notes = coalesce(notes, 'Arizona has no statewide building, residential, plumbing, mechanical, electrical or energy code for private construction; cities and counties choose whether to adopt and enforce codes. The only statewide construction-related code is the State Fire Code adopted by the Office of the State Fire Marshal. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'AZ' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, null), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'CA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Colorado has no statewide building code for private residential or commercial construction; counties and municipalities choose whether to adopt one. Three things do apply statewide. Electrical work follows the board-adopted NEC and plumbing/fuel gas follows the Colorado Plumbing and Fuel Gas Codes, with locals allowed stricter standards. Any local government that has a building code must adopt a minimum energy code when it updates its codes. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'CO' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Connecticut State Building Code applies in every town, city and borough and to state agencies; local building officials enforce it, and local fire marshals enforce the State Fire Safety and Fire Prevention Codes. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, 'https://portal.ct.gov/das/oedm/list-of-local-building-officials'), updated_at = now()
  where id = 'CT' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The District of Columbia has one construction code for the whole District: the 2017 DC Construction Codes (2015 I-codes, 2014 NEC, ASHRAE 90.1-2013 with DC amendments in 12 DCMR), enforced by the DC Department of Buildings. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'DC' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Delaware has no statewide building or residential code: New Castle, Kent and Sussex Counties (and municipalities) adopt and enforce their own building codes. Statewide rules do cover energy (DNREC), plumbing (Division of Public Health) and fire safety (State Fire Prevention Commission). No statewide code for one- and two-family homes; other buildings follow state rules.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'DE' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'awaiting_verification', notes = coalesce(notes, 'The Florida Building Code applies statewide without any local adoption. Counties and municipalities enforce it and may adopt more stringent local technical amendments under limits in § 553.73(4). The Florida Fire Prevention Code is also statewide. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'FL' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Georgia''s mandatory State Minimum Standard Codes (building, residential, fire, plumbing, mechanical, gas, electrical, energy, pool) apply to all construction statewide whether or not the local government enforces them; local governments choose which mandatory codes to enforce and may adopt stricter local amendments after DCA review. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'GA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The State Building Code Council adopts the Hawaii State Building Codes (currently 2018 IBC/IRC/IEBC/IECC, 2018 UPC, 2020 NEC; the fire code is 2024 NFPA 1). Each county amends, adopts and enforces them, and an unadopted state code becomes the interim county code after two years, though that deadline is suspended under a 2025 emergency proclamation. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'HI' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Iowa''s state building code (2024 IBC/IRC/IEBC) is mandatory only for state-owned or state-funded buildings and in local governments that adopt it. Several other codes apply statewide: the energy code (2012 IECC), the state plumbing code (2024 UPC), the state mechanical code (2024 IMC), the electrical code (2023 NEC) and the state fire code (2024 IFC). Local governments may adopt stricter plumbing/mechanical amendments and their own NEC amendments. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, 'https://dial.iowa.gov/licenses/building/plan-review'), updated_at = now()
  where id = 'IA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Idaho''s building codes (IBC, Idaho Residential Code, Idaho Energy Conservation Code, IEBC) are adopted by the Idaho Building Code Board. A city or county applies them only if it runs a building permit program, and it may amend them within limits; the state DOPL handles public buildings and schools. The electrical, plumbing and mechanical codes are adopted statewide by their licensing boards. The fire code is adopted statewide by the State Fire Marshal. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'ID' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Illinois has no statewide building code enforced everywhere. The Illinois Energy Conservation Code and Illinois Plumbing Code apply statewide; since 1/1/2025 local building codes must be at least as stringent as the IBC/IRC for structural design, and jurisdictions without a code fall back to IBC/IRC/NEC under state law. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, 'https://illinois-code-directory.powerappsportals.us/'), updated_at = now()
  where id = 'IL' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Rules of the Fire Prevention and Building Safety Commission (675 IAC) are in force everywhere in Indiana. The state reviews plans for commercial (Class 1) buildings; local units must require compliance and handle local permitting/inspection, including for one- and two-family homes (Class 2). One code applies statewide.'), building_dept_url = coalesce(building_dept_url, 'https://www.in.gov/dhs/fire-and-building-safety/code-enforcement/deputy-building-commissioner-dbc-local-building-official-lbo-list-for-the-state-of-indiana'), updated_at = now()
  where id = 'IN' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Kansas has no statewide building, residential, plumbing, mechanical, energy or electrical code for private construction. Cities and counties decide whether to adopt model codes by reference. The State Fire Marshal''s Kansas Fire Prevention Code applies statewide, except to one- and two-family dwellings. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'KS' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Kentucky has one mandatory Uniform State Building Code (Kentucky Building Code and Kentucky Residential Code) that applies everywhere. Local governments enforce it, while the state reviews larger buildings; permits and inspections for single-family homes are only required where a local ordinance requires them. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'KY' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Louisiana State Uniform Construction Code applies statewide, and every parish and municipality must enforce it (and only it) through certified building code enforcement officers or third-party providers. The Louisiana Uniform Construction Code Commission adopts and amends the codes. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, 'https://arlspublic.lslbc.louisiana.gov/LUCCC/Search/Jurisdiction'), updated_at = now()
  where id = 'LA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Massachusetts State Building Code (780 CMR) is the building code for every city and town and is enforced by local building officials; plumbing/gas (248 CMR), electrical (527 CMR 12) and fire (527 CMR 1) are separate statewide specialized codes. Towns may opt into the stricter Stretch or Specialized energy codes. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'MA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Maryland Building Performance Standards (IBC, IRC, IECC with state changes) apply statewide and are enforced by each county or city, which may adopt local amendments as long as they do not weaken energy, residential sprinkler or wind provisions. Plumbing, electrical and mechanical codes are handled separately (state boards, fire marshal, or local codes). The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, 'https://labor.maryland.gov/labor/build/buildlocal.shtml'), updated_at = now()
  where id = 'MD' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Maine Uniform Building and Energy Code (MUBEC) applies to construction everywhere in Maine, but towns over 4,000 people must enforce it while smaller towns may choose whether to enforce it (and cannot adopt any other building code). Electrical (NEC) and plumbing (UPC) codes are separate statewide trade codes. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'ME' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The single state construction code applies throughout Michigan. Local governments may elect to administer and enforce it; otherwise the county or the state Bureau of Construction Codes does. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, 'https://www.michigan.gov/lara/-/media/Project/Websites/lara/bcc-media/ASD/StatewideJurisdictionList.pdf'), updated_at = now()
  where id = 'MI' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'awaiting_verification', notes = coalesce(notes, 'Missouri has no statewide building, residential, plumbing, mechanical, electrical, fire or energy code for private construction. Counties, cities and fire districts choose and amend their own codes; a county that adopts a building code must use a 1999-or-later nationally recognized code. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, 'https://dnr.mo.gov/energy/efficiency/codes-jurisdiction'), updated_at = now()
  where id = 'MO' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Mississippi has no statewide building code that applies to all construction. Under the 2014 law, counties and cities had to adopt one of the recent editions of the state uniform construction codes unless they opted out by Nov. 30, 2014; the State Fire Marshal enforces a state fire code (2024 IFC/IBC) for public assembly and high-rise buildings where no equivalent local code exists. No statewide code for most private construction; cities and counties choose and enforce their own.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'MS' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Montana''s state building code is adopted by the Department of Labor & Industry and enforced statewide for commercial buildings and residential buildings of five or more units. The state enforces it except where a city, county or town runs a certified program. Homes with fewer than five units and farm/ranch buildings are covered only where a local government has adopted the code; outside those areas, residential energy rules apply through builder self-certification. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, 'https://bsd.dli.mt.gov/building-codes-permits/certified-government'), updated_at = now()
  where id = 'MT' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The North Carolina State Building Code applies throughout the state and is enforced by local inspection departments; local governments may not adopt their own building codes except fire prevention and floodplain rules approved as allowed by law. The 2018 NC codes remain in force because the 2024 NC code''s effective date has been delayed by the legislature. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NC' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The North Dakota State Building Code (2024 IBC, IRC, IMC, IFGC, IECC, IEBC) is not enforced statewide: any city, township or county that chooses to enforce a building code must adopt it, and may amend it. State and local government buildings and schools must comply everywhere. The state electrical, plumbing and fire codes apply statewide. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, 'https://www.commerce.nd.gov/sites/www/files/documents/Community%20Services/Building%20Codes/CodeEnforcementContactList.pdf'), updated_at = now()
  where id = 'ND' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Nebraska''s Legislature adopts a state building code (2018 IBC, IRC, IEBC and UPC). It applies to state buildings and, by default, to any county, city or village that has not adopted its own conforming code, though not to farm construction. The 2018 IECC (Nebraska Energy Code), the 2023 NEC (through the State Electrical Act) and the State Fire Code apply statewide, with local enforcement allowed. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NE' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The New Jersey Uniform Construction Code (N.J.A.C. 5:23) applies statewide to all buildings, enforced by municipal construction offices (or DCA where a municipality does not enforce); municipalities cannot adopt their own construction codes. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NJ' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'New Mexico''s Construction Industries Division (CID) adopts building, residential, existing-building, energy, plumbing, mechanical and electrical codes that apply statewide. They are enforced by CID or by a city or county that has its own full-service building department. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NM' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Nevada has no statewide building code for private construction. Cities and counties may adopt and enforce their own building codes. Two state codes do apply statewide: the energy code (the IECC, adopted by the Governor''s Office of Energy as a minimum that local building codes must include and enforce) and the State Fire Marshal''s fire code regulations. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NV' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The NYS Uniform Fire Prevention and Building Code and Energy Code apply statewide (outside New York City), and are administered and enforced by cities, towns, villages or counties (or the state where a locality opts out). The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'NY' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Ohio Building Code applies statewide to commercial buildings (and residential buildings over three units), enforced by certified local building departments or the state. The Residential Code of Ohio applies to 1-3 family dwellings, but permits and inspections are required only where a certified residential building department has jurisdiction. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'OH' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Oklahoma Uniform Building Code Commission (OUBCC) adopts codes that are the statewide minimum for all residential and commercial construction. Cities and other local governments must meet these minimums and enforce them; they may adopt higher standards, and amendments for local conditions need Commission approval. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'OK' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Oregon has one uniform state building code, made up of specialty codes adopted by the Building Codes Division. It applies in every city and county, and local governments may not enforce different requirements without the director''s authorization. Local building departments, or the state where none exists, run permits and inspections. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, 'https://www.oregon.gov/bcd/lbdd/Pages/index.aspx'), updated_at = now()
  where id = 'OR' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Uniform Construction Code applies statewide. Municipalities that opt in enforce it locally; in opt-out municipalities the Department of Labor & Industry enforces commercial work and owner-hired certified third-party agencies enforce residential work. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'PA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Rhode Island has one State Building Code (RICR Title 510) that applies in every city and town; municipalities enforce it but are prohibited from enacting their own building codes. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'RI' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'South Carolina''s mandatory codes, as modified by the Building Codes Council, must be enforced by every municipality and county; local changes are allowed only as Council-approved local modifications, and each locality sets its own administrative procedures. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'SC' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Tennessee sets statewide minimum codes enforced by the State Fire Marshal, but approved ''exempt'' cities and counties enforce their own adopted codes. The statewide residential code for one- and two-family homes applies unless a county or city has opted out; electrical inspections follow the state-adopted NEC. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, 'https://www.tn.gov/commerce/fire/codes-enforcement/exempt-jurisdictions.html'), updated_at = now()
  where id = 'TN' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'In Texas, state law makes the IRC and IBC (as they existed on May 1, 2012) the minimum building codes only inside city limits. Cities enforce them, may adopt newer editions and may amend them after a public hearing. Unincorporated county areas have no state building code, but the state energy code and electrical code apply statewide, and licensed plumbers there must follow a board-adopted plumbing code. Some codes apply statewide; others only where a city or county adopts them.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'TX' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Utah State Construction Code is adopted by the Legislature in statute (Title 15A) and applies uniformly statewide. Local building departments (compliance agencies) enforce it, and cities and counties may not adopt anything more restrictive except as the Legislature allows. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'UT' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Virginia Uniform Statewide Building Code applies statewide and supersedes local building codes; every local building department must enforce it, and localities cannot amend it. The Statewide Fire Prevention Code applies statewide but local enforcement is optional. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'VA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Vermont''s Fire & Building Safety Code (IBC, NFPA 1/101) applies only to ''public buildings'' (commercial, multifamily, rentals, etc.); there is no statewide building code for owner-occupied single-family homes, though the residential energy code (RBES) applies statewide and plumbing rules apply to homes on public water/sewer. No statewide code for one- and two-family homes; other buildings follow state rules.'), building_dept_url = coalesce(building_dept_url, 'https://firesafety.vermont.gov/buildingcode/municipalinsp'), updated_at = now()
  where id = 'VT' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'The Washington State Building Code (IBC, IRC, IMC/IFGC, IFC, UPC and the Washington State Energy Code, as amended by the State Building Code Council) is in effect in every county and city and is enforced by local building departments. Cities and counties may amend it but may not lower its minimum performance standards; the residential energy code is both the maximum and minimum. Electrical work is regulated statewide by L&I under chapter 296-46B WAC. The state sets a minimum code; cities and counties enforce it, sometimes with local amendments.'), building_dept_url = coalesce(building_dept_url, null), updated_at = now()
  where id = 'WA' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Wisconsin writes and enforces its own statewide codes through DSPS. The Uniform Dwelling Code (UDC) covers new one- and two-family homes everywhere in the state. A municipality with delegated authority issues the permits and does the inspections; where none has it, DSPS or a state-appointed inspector does. One code applies statewide.'), building_dept_url = coalesce(building_dept_url, 'https://dsps.wi.gov/plan-reviews-and-permits/delegated-agents/'), updated_at = now()
  where id = 'WI' and coverage = 'awaiting_verification';
update public.academy_kb_jurisdictions set coverage = 'partial', notes = coalesce(notes, 'Wyoming has no statewide residential building or energy code. The Council on Fire Prevention and Electrical Safety adopts the IBC, IEBC, IFC, IMC and IFGC as minimum fire and life-safety standards, which the State Fire Marshal enforces through plan review of public and government buildings. The NEC applies statewide to electrical installations. Cities and counties may take over enforcement if they adopt standards at least as stringent; houses are otherwise regulated only where a local government has adopted a code. No statewide code for one- and two-family homes; other buildings follow state rules.'), building_dept_url = coalesce(building_dept_url, 'https://wsfm.wyo.gov/electrical-safety'), updated_at = now()
  where id = 'WY' and coverage = 'awaiting_verification';

select set_config('academy.kb_verifying', 'off', false);
