insert into public.academy_kb_adoptions (id, jurisdiction_id, source_id, kind, replaces_family, scope_note, authority_citation, official_url, effective_date, expiration_date, local_confirmation_required, trades, status, last_verified_at, notes) values
  (md5('academykb:adoption:st:AK:ibc:2021')::uuid, 'AK', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'International Building Code as adopted by 13 AAC 50.020. Commercial and other non-residential buildings. Applies statewide. Applies statewide to buildings regulated by the Division of Fire and Life Safety (Department of Public Safety); detached one-, two- and three-family dwellings and small townhouses are excepted from the IBC scope. The State Fire Marshal may defer plan review/enforcement to qualifying municipalities (13 AAC 50.075), which adopt their own codes. Effective date from the Lt. Governor''s regulation filing notice for 13 AAC 50-55 (Filed 9/28/2022, Effective 10/28/2022). Plans are reviewed by the state; the state does not issue building permits.', '13 AAC 50.020', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.020&secEnd=13.50.020', '2022-10-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:iebc:2021')::uuid, 'AK', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'International Existing Building Code as adopted by 13 AAC 50.021. Commercial and other non-residential buildings. Applies statewide. Applies statewide to buildings regulated by the Division of Fire and Life Safety (Department of Public Safety); detached one-, two- and three-family dwellings and small townhouses are excepted from the IBC scope. The State Fire Marshal may defer plan review/enforcement to qualifying municipalities (13 AAC 50.075), which adopt their own codes. Effective date from the Lt. Governor''s regulation filing notice for 13 AAC 50-55 (Filed 9/28/2022, Effective 10/28/2022).', '13 AAC 50.021', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.021&secEnd=13.50.021', '2022-10-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:imc:2021')::uuid, 'AK', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'International Mechanical Code as adopted by 13 AAC 50.023. Commercial and other non-residential buildings. Applies statewide. Applies statewide to buildings regulated by the Division of Fire and Life Safety (Department of Public Safety); detached one-, two- and three-family dwellings and small townhouses are excepted from the IBC scope. The State Fire Marshal may defer plan review/enforcement to qualifying municipalities (13 AAC 50.075), which adopt their own codes. Effective date from the Lt. Governor''s regulation filing notice for 13 AAC 50-55 (Filed 9/28/2022, Effective 10/28/2022).', '13 AAC 50.023', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.023&secEnd=13.50.023', '2022-10-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:ifgc:2021')::uuid, 'AK', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'International Fuel Gas Code (limited chapters) as adopted by 13 AAC 50.024. Commercial and other non-residential buildings. Applies statewide. Applies statewide to buildings regulated by the Division of Fire and Life Safety (Department of Public Safety); detached one-, two- and three-family dwellings and small townhouses are excepted from the IBC scope. The State Fire Marshal may defer plan review/enforcement to qualifying municipalities (13 AAC 50.075), which adopt their own codes. Effective date from the Lt. Governor''s regulation filing notice for 13 AAC 50-55 (Filed 9/28/2022, Effective 10/28/2022). Only IFGC section 304 and chapters 6-7 are adopted; other fuel gas piping is governed by the Uniform Plumbing Code (8 AAC 63.010).', '13 AAC 50.024', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.024&secEnd=13.50.024', '2022-10-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:ifc:2021')::uuid, 'AK', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'International Fire Code as adopted by 13 AAC 50.025. Applies statewide. State fire code enforced by the Division of Fire and Life Safety; deferred municipalities enforce locally (13 AAC 50.075).', '13 AAC 50.025', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.025&secEnd=13.50.025', '2022-10-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:nec:2020')::uuid, 'AK', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'National Electrical Code as adopted by 8 AAC 70.025. Applies statewide. Minimum electrical code for the state. Department of Labor (Mechanical Inspection) inspects commercial structures and dwellings of three-plex and above; Anchorage and Fairbanks inspect under agreements. A state certificate of fitness is required for NEC work everywhere in Alaska.', '8 AAC 70.025(a)', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=8.70.025&secEnd=8.70.025', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AK:upc:2018')::uuid, 'AK', md5('academykb:source:upc-2018')::uuid, 'adopts', null, 'Uniform Plumbing Code as adopted by 8 AAC 63.010. Applies statewide. Minimum plumbing standard statewide (also covers gas and fuel piping). State plumbing inspection jurisdiction is communities of 2,500+ population; Anchorage and Fairbanks inspect under agreements.', '8 AAC 63.010; AS 18.60.705', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=8.63.010&secEnd=8.63.010', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:ibc:2021')::uuid, 'AL', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Alabama State Building Code (2021 IBC with portions of 2024 IBC). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:iebc:2021')::uuid, 'AL', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Alabama State Building Code - 2021 International Existing Building Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:ipc:2021')::uuid, 'AL', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Alabama State Building Code - 2021 International Plumbing Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:ifgc:2021')::uuid, 'AL', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Alabama State Building Code - 2021 International Fuel Gas Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:imc:2021')::uuid, 'AL', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Alabama State Building Code - 2021 International Mechanical Code (portions of 2024 IMC). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:nec:2020')::uuid, 'AL', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'Alabama State Building Code - 2020 National Electrical Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:ashrae_90_1:2013')::uuid, 'AL', md5('academykb:source:ashrae_90_1-2013')::uuid, 'adopts', null, 'Alabama State Building Code - ASHRAE 90.1-2013. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Alabama State Building Code (DCM): applies only to state-owned/state-funded work, public and private K-12 schools, public postsecondary schools, hotels/motels and movie theaters; not to other private commercial or residential buildings, where local codes govern.', 'Ala. Admin. Code r. 355-12-1-.01', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:ifc:2021')::uuid, 'AL', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'State Fire Marshal regulation - 2021 International Fire Code. Adopted as a regulation of the State Fire Marshal for projects whose architectural services contract is dated on or after the rule''s effective date; Chapter 1 Part 2 (administration) not adopted. Geographic/occupancy reach of SFM enforcement versus local fire codes was not confirmed (statewide left null). Rule history shows revisions effective 1/1/2023 and 1/1/2025.', 'Ala. Admin. Code r. 482-2-101-.02', 'https://admincode.legislature.state.al.us/api/rule/482-2-101-.02', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AL:irc:alabama-residential-building-code')::uuid, 'AL', md5('academykb:source:st:AL:irc:alabama-residential-building-code')::uuid, 'adopts', null, 'Alabama Residential Building Code. Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Adopted by the Home Builders Licensure Board; enforced only by local jurisdictions with residential permitting/inspection programs; does not supersede local residential codes in effect on Jan. 1, 2027; locals may adopt codes that comply with or exceed it. Builders must follow the applicable residential code beginning January 1, 2027. The previous AERC rule (Ala. Admin. Code r. 305-2-4-.09) adopted the 2015 IRC effective Oct. 1, 2016, and HBLB states it applies the 2015 IRC in investigations where no local code exists.', 'Code of Ala. 1975, § 34-14A-12 (Act 2024-443)', 'https://hblb.alabama.gov/wp-content/uploads/2026/03/HBLB-Law-Effective-October-1-2025-Reg-Effective-November-14-2025.pdf', null, null, true, '{}'::text[], 'pending_review', null, 'Could not find an official record of which IRC edition the Home Builders Licensure Board has adopted as the Alabama Residential Building Code (the advisory council was to recommend one by Oct. 1, 2025) or its effective date.'),
  (md5('academykb:adoption:st:AL:iecc:alabama-commercial-energy-code-formerly-alabama-en')::uuid, 'AL', md5('academykb:source:st:AL:iecc:alabama-commercial-energy-code-formerly-alabama-en')::uuid, 'adopts', null, 'Alabama Commercial Energy Code (formerly Alabama Energy and Residential Codes). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Adoption authority moved from ADECA to the Alabama Licensing Board for General Contractors effective Oct. 1, 2024; a proposed code was due by Dec. 31, 2025. Old AERC rule: 2015 IECC or ASHRAE 90.1-2013, effective Jan. 1, 2016, enforced where locals adopt.', 'Act 2024-443; formerly Ala. Admin. Code r. 305-2-4-.08', 'https://admincode.legislature.state.al.us/api/chapter/305-2-4', null, null, true, '{}'::text[], 'pending_review', null, 'The quoted AERC rule text comes from an administrative code supplement dated 9/30/17, and adoption authority has since moved to the Licensing Board for General Contractors. Whether a new commercial energy code has been adopted could not be confirmed.'),
  (md5('academykb:adoption:st:AR:imc:2021')::uuid, 'AR', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'International Mechanical Code as adopted by the Arkansas HVACR Licensing Board. Applies statewide. Standard for the conduct of HVACR work statewide.', '17 CAR § 261-122', 'https://labor.arkansas.gov/wp-content/uploads/17CARpt.261.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:AR:nec:national-electrical-code-as-adopted-by-the-board-o')::uuid, 'AR', md5('academykb:source:st:AR:nec:national-electrical-code-as-adopted-by-the-board-o')::uuid, 'adopts', null, 'National Electrical Code as adopted by the Board of Electrical Examiners. Applies statewide. Rule text marked ''Final'' adopts the 2026 NEC with state exceptions (e.g., no AFCI/GFCI for dwelling laundry areas or refrigerator/microwave).', '17 CAR § 210-401; Ark. Code § 20-31-101 et seq.', 'https://labor.arkansas.gov/wp-content/uploads/17CARpt-210-Final.pdf', null, null, true, '{}'::text[], 'pending_review', null, 'A March 21, 2026 hearing notice proposed updating ''from the 2020 edition of the National Electrical Code''; a ''Final'' rule PDF (created August 2026) adopts the 2026 NEC, but no official source found states that it has taken effect or its effective date. The in-force edition today is either 2020 or 2026.'),
  (md5('academykb:adoption:st:AZ:ifc:arizona-state-fire-code')::uuid, 'AZ', md5('academykb:source:st:AZ:ifc:arizona-state-fire-code')::uuid, 'adopts', null, 'Arizona State Fire Code. Applies statewide. The State Fire Marshal enforces the state fire code throughout Arizona, except in cities of 100,000 or more people that have their own nationally recognized fire code and have taken over jurisdiction by ordinance. Those cities must still follow the state fire code in state- and county-owned buildings. The code does not cover family dwellings with fewer than five units.', 'A.R.S. 37-1383(A)(2), (A)(5); Ariz. Admin. Code R4-36-201', 'https://www.azleg.gov/ars/37/01383.htm', null, null, true, '{}'::text[], 'pending_review', null, 'The statute confirms a statewide State Fire Code. The edition is in rule R4-36-201, but the official rule sites (apps.azsos.gov Title 4 Ch. 36 PDF and dffm.az.gov) blocked automated access with Cloudflare 403 responses. Non-official copies (Cornell LII, Justia) show the 2018 IFC, last amended at 27 A.A.R. 2797, effective 1/7/2022. Someone needs to read the edition and effective date on the official rule text.'),
  (md5('academykb:adoption:st:CA:ibc:2024')::uuid, 'CA', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, '2025 California Building Code (Title 24, Part 2). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Two volumes. Applies to all occupancies; one- and two-family dwellings and townhouses fall under the CRC.', 'Cal. Code Regs., tit. 24, pt. 2; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:irc:2024')::uuid, 'CA', md5('academykb:source:irc-2024')::uuid, 'adopts', null, '2025 California Residential Code (Title 24, Part 2.5). Residential. Applies statewide. Local amendments are allowed.', 'Cal. Code Regs., tit. 24, pt. 2.5; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:nec:2023')::uuid, 'CA', md5('academykb:source:nec-2023')::uuid, 'adopts', null, '2025 California Electrical Code (Title 24, Part 3). Applies statewide. Local amendments are allowed.', 'Cal. Code Regs., tit. 24, pt. 3; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:umc:2024')::uuid, 'CA', md5('academykb:source:umc-2024')::uuid, 'adopts', null, '2025 California Mechanical Code (Title 24, Part 4). Applies statewide. Local amendments are allowed.', 'Cal. Code Regs., tit. 24, pt. 4; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:upc:2024')::uuid, 'CA', md5('academykb:source:upc-2024')::uuid, 'adopts', null, '2025 California Plumbing Code (Title 24, Part 5). Applies statewide. Local amendments are allowed. California has no separate IFGC adoption; fuel gas is assumed to be covered within the CPC/CMC (not separately verified).', 'Cal. Code Regs., tit. 24, pt. 5; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:ifc:2024')::uuid, 'CA', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, '2025 California Fire Code (Title 24, Part 9). Applies statewide. Local amendments are allowed.', 'Cal. Code Regs., tit. 24, pt. 9; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:iebc:2024')::uuid, 'CA', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, '2025 California Existing Building Code (Title 24, Part 10). Applies statewide. Local amendments are allowed.', 'Cal. Code Regs., tit. 24, pt. 10; Cal. Health & Safety Code § 18901 et seq.', 'https://www.dgs.ca.gov/BSC/Codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CA:state_energy:2025-california-energy-code-building-energy-effici')::uuid, 'CA', md5('academykb:source:st:CA:state_energy:2025-california-energy-code-building-energy-effici')::uuid, 'adopts', null, '2025 California Energy Code (Building Energy Efficiency Standards, Title 24, Part 6). Applies statewide. Local amendments are allowed. A state-written code adopted entirely by the California Energy Commission, not based on the IECC. It applies to permit applications filed on or after Jan 1, 2026. Under the Title 24 rules, local amendments must be more restrictive.', 'Cal. Code Regs., tit. 24, pt. 6', 'https://www.energy.ca.gov/programs-and-topics/programs/building-energy-efficiency-standards/2025-building-energy-efficiency', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CO:nec:2026')::uuid, 'CO', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'National Electrical Code as adopted by the Colorado State Electrical Board. Applies statewide. Local amendments are allowed. Statewide minimum standard for electrical installations. Under C.R.S. 12-115-107, cities, counties and qualified higher-education institutions may enforce more stringent standards if they file a copy with the board.', '3 CCR 710-1, Rule 1.5; C.R.S. 12-115-107(2)(a)', 'https://www.sos.state.co.us/CCR/GenerateRulePdf.do?ruleVersionId=12714&fileName=3%20CCR%20710-1', '2026-08-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CO:ipc:2024')::uuid, 'CO', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'Colorado Plumbing Code (2024 IPC plus 2024 IRC Chapters 25-32). Applies statewide. Local amendments are allowed. Statewide minimum plumbing standard. Under C.R.S. 12-155-106(2), locals may amend it if the amendments are at least equal to the state minimums. The effective date comes from the rule''s history note ''Rules 1.2 eff. 08/14/2026''.', '3 CCR 720-1, Rule 1.2(A); C.R.S. 12-155-106', 'https://www.sos.state.co.us/CCR/GenerateRulePdf.do?ruleVersionId=12668&fileName=3%20CCR%20720-1', '2026-08-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CO:ifgc:2024')::uuid, 'CO', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'Colorado Fuel Gas Code (2024 IFGC plus 2024 IRC Chapter 24 sections). Applies statewide. Local amendments are allowed. Covers fuel gas piping and systems throughout Colorado. IFGC Sections 412 and 413 are excluded.', '3 CCR 720-1, Rule 1.2(B); C.R.S. 12-155-106', 'https://www.sos.state.co.us/CCR/GenerateRulePdf.do?ruleVersionId=12668&fileName=3%20CCR%20720-1', '2026-08-14'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:CO:iecc:2021')::uuid, 'CO', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Minimum energy code for local governments that adopt building codes (C.R.S. 30-28-211 / 31-15-602, HB22-1362). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. This is not a state-enforced code. Local governments that already have building codes and updated them from July 1, 2023 to before July 1, 2026 had to adopt an energy code at least equal to the 2021 IECC plus the Model Electric Ready and Solar Ready Code. For updates on or after July 1, 2026, the minimum is the Model Low Energy and Carbon Code; the model edition shown here (2021) does not reflect that newer requirement. Rural counties have a different, older-edition option.', 'C.R.S. 30-28-211(3.5); C.R.S. 31-15-602 (as amended by HB22-1362)', 'https://leg.colorado.gov/sites/default/files/2022a_1362_signed.pdf', null, null, true, '{}'::text[], 'pending_review', null, 'The text comes from the 2022 session law, not the current codified statute, and was not checked against later amendments. The current minimum for code updates after July 1, 2026 is the Model Low Energy and Carbon Code (based on the 2024 IECC per news and search leads), whose official text and edition I could not read: energyoffice.colorado.gov returned 403. Rural-county rules were not fully reviewed.'),
  (md5('academykb:adoption:st:CT:ibc:2021')::uuid, 'CT', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IBC portion). Commercial and other non-residential buildings. Applies statewide. Applies to all buildings other than those covered by the IRC portion. Effective date per DAS: codes took effect October 1, 2022; applies to projects whose primary permit was applied for on or after that date.', 'Conn. Gen. Stat. sec. 29-252; 29-252a', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:irc:2021')::uuid, 'CT', md5('academykb:source:irc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IRC portion). Residential. Applies statewide. Detached one- and two-family dwellings and townhouses not more than three stories above grade plane.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:iebc:2021')::uuid, 'CT', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IEBC portion). Applies statewide.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:ipc:2021')::uuid, 'CT', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IPC portion). Applies statewide.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:imc:2021')::uuid, 'CT', md5('academykb:source:imc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IMC portion). Applies statewide.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:iecc:2021')::uuid, 'CT', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2021 IECC portion). Applies statewide. Energy code for residential and commercial buildings.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:nec:2020')::uuid, 'CT', md5('academykb:source:nec-2020')::uuid, 'adopts', null, '2022 Connecticut State Building Code (2020 NFPA 70 portion). Applies statewide.', 'Conn. Gen. Stat. sec. 29-252', 'https://portal.ct.gov/das/office-of-state-building-inspector/connecticut-state-building-code/regulations', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:ifc:2021')::uuid, 'CT', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, '2022 Connecticut State Fire Safety Code (Part III, International Fire Code). Applies statewide. Part III covers new construction, renovation or change of use (permits issued on or after Jan 1, 2006); existing older buildings fall under Part IV (NFPA 101, 2021 edition). Enforced by local fire marshals.', 'Conn. Gen. Stat. sec. 29-292', 'https://portal.ct.gov/das/services-for-agencies-and-municipalities/safety-codes-and-inspections/fire-safety-prevention', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:CT:nfpa1:2021')::uuid, 'CT', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, '2022 Connecticut State Fire Prevention Code. Applies statewide. Maintenance/operations fire code; references NFPA 54 National Fuel Gas Code, 2021 edition.', 'Connecticut State Fire Prevention Code (adopted by State Fire Marshal under Conn. Gen. Stat. ch. 541)', 'https://portal.ct.gov/das/services-for-agencies-and-municipalities/safety-codes-and-inspections/fire-safety-prevention', '2022-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:ibc:2015')::uuid, 'DC', md5('academykb:source:ibc-2015')::uuid, 'adopts', null, '2017 District of Columbia Building Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. District-wide; DOB issues permits. Projects in the pipeline may use prior editions under the transitory provision (12-A DCMR §123).', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:irc:2015')::uuid, 'DC', md5('academykb:source:irc-2015')::uuid, 'adopts', null, '2017 District of Columbia Residential Code. Residential. Applies statewide. Local governments may not amend it. District-wide; DOB is the single permitting authority.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:iebc:2015')::uuid, 'DC', md5('academykb:source:iebc-2015')::uuid, 'adopts', null, '2017 District of Columbia Existing Building Code. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:ipc:2015')::uuid, 'DC', md5('academykb:source:ipc-2015')::uuid, 'adopts', null, '2017 District of Columbia Plumbing Code. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:imc:2015')::uuid, 'DC', md5('academykb:source:imc-2015')::uuid, 'adopts', null, '2017 District of Columbia Mechanical Code. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:ifgc:2015')::uuid, 'DC', md5('academykb:source:ifgc-2015')::uuid, 'adopts', null, '2017 District of Columbia Fuel Gas Code. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:ifc:2015')::uuid, 'DC', md5('academykb:source:ifc-2015')::uuid, 'adopts', null, '2017 District of Columbia Fire Code. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:iecc:2015')::uuid, 'DC', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, '2017 District of Columbia Energy Conservation Code (residential). Residential. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:ashrae_90_1:2013')::uuid, 'DC', md5('academykb:source:ashrae_90_1-2013')::uuid, 'adopts', null, '2017 District of Columbia Energy Conservation Code (commercial, ASHRAE 90.1-2013). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DC:nec:2014')::uuid, 'DC', md5('academykb:source:nec-2014')::uuid, 'adopts', null, '2017 District of Columbia Electrical Code (2014 NEC). Applies statewide. Local governments may not amend it.', '12 DCMR (District of Columbia Construction Codes Supplement of 2017), Subtitles A-M', 'https://dob.dc.gov/node/1613981', '2020-05-29'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DE:iecc:2024')::uuid, 'DE', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'Delaware State Energy Conservation Code (residential). Residential. Applies statewide. Local amendments are allowed. Minimum energy code for new 1- and 2-family dwellings and residential buildings 3 stories or less; county and municipal codes must meet it within 12 months of DNREC adoption (16 Del. C. § 7602(a)); locals may adopt stretch codes. Includes Appendix RE (EV charging) with amendments.', '7 DE Admin. Code 2101; 16 Del. C. § 7602', 'https://dnrec.delaware.gov/energy-climate/efficiency/building-energy-codes/', '2026-04-11'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DE:ashrae_90_1:2022')::uuid, 'DE', md5('academykb:source:ashrae_90_1-2022')::uuid, 'adopts', null, 'Delaware State Energy Conservation Code (commercial and high-rise residential: 2024 IECC or ASHRAE 90.1-2022). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Commercial compliance options: 2024 IECC prescriptive, 2024 IECC simulated performance, or ASHRAE 90.1-2022; includes Appendix CB solar-ready zone with amendments. Local codes must meet it within 12 months; locals may adopt stretch codes.', '7 DE Admin. Code 2101; 16 Del. C. § 7602', 'https://dnrec.delaware.gov/energy-climate/efficiency/building-energy-codes/', '2026-04-11'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DE:ipc:2021')::uuid, 'DE', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, '2021 State of Delaware Plumbing Code. Applies statewide. Local amendments are allowed. Every county, city and municipality must enforce the IPC as adopted by the Division of Public Health; local additions/modifications require DPH approval (16 Del. C. § 7904). DPH runs plumbing permits/inspections in Kent and Sussex Counties.', '16 DE Admin. Code 4455; 16 Del. C. §§ 7903-7904', 'https://dhss.delaware.gov/dph/hsp/plumbing/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DE:nfpa1:2024')::uuid, 'DE', md5('academykb:source:nfpa1-2024')::uuid, 'adopts', null, 'Delaware State Fire Prevention Regulations (Regulation 701). Applies statewide. Adopts NFPA 1 (2024) and NFPA 101 Life Safety Code (2024) plus other NFPA standards, including NFPA 54 National Fuel Gas Code (2024) and NFPA 58 (2024).', '1 DE Admin. Code 701 (State Fire Prevention Commission)', 'https://statefiremarshal.delaware.gov/', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:DE:nec:2023')::uuid, 'DE', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'National Electrical Code (NFPA 70) as adopted in the Delaware State Fire Prevention Regulations. Applies statewide. Board of Electrical Examiners rules reportedly require licensees to follow the NEC as adopted by the State Fire Prevention Commission (not verified on an official page); local building codes may also adopt the NEC.', '1 DE Admin. Code 701, Chapter 7', 'https://statefiremarshal.delaware.gov/', '2026-01-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Edition/date verified from State Fire Marshal notice, but the link between the fire regulations'' NEC and the electrical licensing/inspection requirement (24 DE Admin. Code 1400) was not confirmed on an official page; reviewer should confirm NEC applies statewide to all electrical installations.'),
  (md5('academykb:adoption:st:FL:ibc:2021')::uuid, 'FL', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Building. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Statewide. Florida adds its own provisions, including High-Velocity Hurricane Zone rules for Miami-Dade and Broward. Locals may adopt more stringent technical amendments, no more than once every 6 months, under § 553.73(4).', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:irc:2021')::uuid, 'FL', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Residential. Residential. Applies statewide. Local amendments are allowed.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:iebc:2021')::uuid, 'FL', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Existing Building. Applies statewide. Local amendments are allowed.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:imc:2021')::uuid, 'FL', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Mechanical. Applies statewide. Local amendments are allowed.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:ipc:2021')::uuid, 'FL', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Plumbing. Applies statewide. Local amendments are allowed.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:ifgc:2021')::uuid, 'FL', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Fuel Gas. Applies statewide. Local amendments are allowed.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:iecc:2021')::uuid, 'FL', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – Energy Conservation. Applies statewide. Local amendments are allowed. Energy volume of the FBC, based on the 2021 I-Codes. Whether ASHRAE 90.1 is allowed as an alternative was not checked on an official source.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:nec:2020')::uuid, 'FL', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'Florida Building Code, 8th Edition (2023) – electrical provisions (National Electrical Code). Applies statewide. Local amendments are allowed. The Commission selected the 2020 NEC as a model code for the 8th Edition. The adopting text for the electrical provisions was not read directly.', 'Fla. Stat. § 553.73; Fla. Admin. Code R. 61G20-1.001', 'https://www.floridabuilding.org/c/default.aspx', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:FL:nfpa1:2021')::uuid, 'FL', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, 'Florida Fire Prevention Code, 8th Edition (2023) – NFPA 1, Fire Code, Florida 2021 Edition (with NFPA 101). Applies statewide. Local amendments are allowed. State Fire Marshal code made up of NFPA 1 and NFPA 101, Florida editions. The SFM page says local amendments are enforceable only by the local jurisdiction. The 9th Edition takes effect 2026-12-31.', 'Fla. Admin. Code R. 69A-60.002, 69A-60.003; Fla. Stat. § 633.202', 'https://www.myfloridacfo.com/division/sfm/bfp/florida-fire-prevention-code', '2023-12-31'::date, null, true, '{}'::text[], 'pending_review', null, 'Official adoption page or citation missing.'),
  (md5('academykb:adoption:st:GA:ibc:2024')::uuid, 'GA', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'Georgia State Minimum Standard Building Code (International Building Code with Georgia State Amendments). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Local amendments must be more stringent, based on local climatic/geologic/topographic/public-safety factors, and submitted to DCA for review (O.C.G.A. § 8-2-25(c)). Further GA amendments to the 2024 IBC take effect 2027-01-01.', 'O.C.G.A. § 8-2-23 (Uniform Codes Act, O.C.G.A. Title 8, Ch. 2)', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:irc:2024')::uuid, 'GA', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'Georgia State Minimum Standard One- and Two-Family Dwelling Code (IRC with Georgia Amendments). Residential. Applies statewide. Local amendments are allowed. DCA omitted the IRC plumbing, electrical and energy chapters; one- and two-family dwellings use the IPC, NEC and IECC (Georgia versions) instead.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:ipc:2024')::uuid, 'GA', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'Georgia State Minimum Standard Plumbing Code (IPC with Georgia Amendments). Applies statewide. Local amendments are allowed.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:imc:2024')::uuid, 'GA', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'Georgia State Minimum Standard Mechanical Code (IMC with Georgia Amendments). Applies statewide. Local amendments are allowed.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:ifgc:2024')::uuid, 'GA', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'Georgia State Minimum Standard Gas Code (IFGC with Georgia Amendments). Applies statewide. Local amendments are allowed.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:nec:2023')::uuid, 'GA', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Georgia State Minimum Standard Electrical Code (NEC with Georgia Amendments). Applies statewide. Local amendments are allowed. 2026 Georgia Amendments to the 2023 NEC took effect 2026-01-01; the 2023 NEC base edition was already in force before that.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:iecc:2015')::uuid, 'GA', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, 'Georgia State Minimum Standard Energy Code (IECC with Georgia State Supplements and Amendments). Applies statewide. Local amendments are allowed. Commercial projects may comply via the IECC or ASHRAE/IESNA 90.1-2013 (COMcheck); Georgia supplements/amendments revised 2020, 2022 and 2023.', 'O.C.G.A. § 8-2-23', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:GA:iebc:2018')::uuid, 'GA', md5('academykb:source:iebc-2018')::uuid, 'adopts', null, 'Georgia State Minimum Standard Existing Building Code (permissive). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Permissive code: applies only where a local government adopts it by ordinance/resolution. DCA has published 2024 IEBC Georgia amendments marked effective January 1, 2027.', 'O.C.G.A. § 8-2-25(b)', 'https://dca.georgia.gov/community-assistance/construction-codes/current-state-minimum-codes-construction', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:HI:irc:2018')::uuid, 'HI', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'Hawaii State Residential Code. Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025). County deadline for this code was November 17, 2022.', 'HRS 107-24, 107-25, 107-28', 'https://ags.hawaii.gov/bcc/building-code-rules/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:HI:ibc:2018')::uuid, 'HI', md5('academykb:source:ibc-2018')::uuid, 'adopts', null, 'Hawaii State Building Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025). County deadline was April 20, 2023.', 'HRS 107-24, 107-25, 107-28', 'https://ags.hawaii.gov/bcc/building-code-rules/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:HI:iebc:2018')::uuid, 'HI', md5('academykb:source:iebc-2018')::uuid, 'adopts', null, 'Hawaii State Existing Building Code. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025).', 'HRS 107-24, 107-25, 107-28', 'https://ags.hawaii.gov/bcc/building-code-rules/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:HI:iecc:2018')::uuid, 'HI', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'Hawaii State Energy Code (2018 IECC with amendments). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025). Effective date is the SBCC adoption date; county deadline was December 15, 2022.', 'HRS 107-24, 107-25, 107-28', 'https://ags.hawaii.gov/bcc/building-code-rules/', '2020-12-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:HI:upc:2018')::uuid, 'HI', md5('academykb:source:upc-2018')::uuid, 'adopts', null, 'Hawaii State Plumbing Code. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025). The code states its provisions ''are State standards and are enforced when adopted by the counties or as an interim code if the counties fail to adopt within the required period.'' The posted document is labeled as proposed amendments, version 1.6.', 'HAR ch. 3-183; HRS 107-25', 'https://ags.hawaii.gov/bcc/building-code-rules/', '2020-05-19'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:HI:nec:2020')::uuid, 'HI', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'Hawaii State Electrical Code (2020 NEC). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Counties must amend and adopt the state code within two years (HRS 107-28(a)); otherwise it becomes the interim county code (HRS 107-28(b)). State building designs must comply (HRS 107-27). The two-year default deadline is currently suspended by the Governor''s 15th Emergency Proclamation on Affordable Housing (Sept. 23, 2025). County deadline was March 14, 2024.', 'HRS 107-24, 107-25, 107-28', 'https://ags.hawaii.gov/bcc/building-code-rules/', '2022-03-15'::date, null, true, '{}'::text[], 'pending_review', null, 'The SBCC ''Building Code Rules'' page labels this link ''State Electric Code – 2018 NFPA 70'', but the linked adoption document adopts the 2020 NEC (there is no 2018 NFPA 70 edition). This is probably a labeling error, but official sources conflict.'),
  (md5('academykb:adoption:st:HI:nfpa1:2024')::uuid, 'HI', md5('academykb:source:nfpa1-2024')::uuid, 'adopts', null, 'Hawaii State Fire Code (2024 NFPA 1 with amendments). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Adopted by the State Fire Council and part of the Hawaii State Building Codes under HRS 107-25. Counties may require permits by ordinance; whether county adoption is required was not confirmed.', 'HRS 132-3; HRS 107-25', 'https://ags.hawaii.gov/bcc/building-code-rules/', '2025-09-05'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:ibc:2024')::uuid, 'IA', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'Iowa State Building Code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Applies to state-owned and state-funded buildings, and in jurisdictions that adopt the state building code by ordinance (Iowa Code 103A.10). Cities over 15,000 without a nationally recognized local code must enforce it. Rules moved from 661 IAC to 481 IAC on 11/26/25.', 'Iowa Admin. Code r. 481—301.3(103A); Iowa Code ch. 103A', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.301.pdf', '2025-09-10'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:irc:2024')::uuid, 'IA', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'Iowa State Building Code – residential construction requirements. Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Same applicability as the state building code (state buildings and adopting jurisdictions). Iowa deletes R309 (townhouse sprinklers).', 'Iowa Admin. Code r. 481—301.8(103A)', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.301.pdf', '2025-09-10'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:iebc:2024')::uuid, 'IA', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'Iowa State Building Code – existing buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Same applicability as the state building code.', 'Iowa Admin. Code r. 481—301.7(103A)', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.301.pdf', '2025-09-10'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:iecc:2012')::uuid, 'IA', md5('academykb:source:iecc-2012')::uuid, 'adopts', null, 'Iowa residential energy code (State Building Code Part 3). Residential. Applies statewide. Applies statewide to residential buildings of three or fewer stories. Remodeling or renovation of one- and two-family dwellings is excluded. Under Iowa Code 103A.10(4)-(5) the energy provisions apply to all construction in the state.', 'Iowa Admin. Code r. 481—301.24(103A); Iowa Code 103A.10(4)', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.301.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:iecc:2012')::uuid, 'IA', md5('academykb:source:iecc-2012')::uuid, 'adopts', null, 'Iowa nonresidential energy code (State Building Code Part 3). Commercial and other non-residential buildings. Applies statewide. Applies statewide to commercial buildings and to residential buildings of four or more stories.', 'Iowa Admin. Code r. 481—301.25(103A); Iowa Code 103A.10(4)', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.301.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:upc:2024')::uuid, 'IA', md5('academykb:source:upc-2024')::uuid, 'adopts', null, 'Iowa State Plumbing Code. Applies statewide. Local amendments are allowed. Applies to plumbing throughout Iowa. Locals may not adopt other plumbing codes but may adopt stricter amendments filed with the board. Fuel gas piping follows UPC Chapter 12 (r. 481—425.3).', 'Iowa Admin. Code r. 481—425.1(105); Iowa Code 105.4', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.425.pdf', '2025-03-26'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:imc:2024')::uuid, 'IA', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'Iowa State Mechanical Code. Applies statewide. Local amendments are allowed. Iowa replaces IMC references to the IFGC with NFPA 54 and NFPA 58 (current editions), 661—Chapter 226 and the state plumbing code. Iowa Code 105.4 lets adopting locals adopt more restrictive standards.', 'Iowa Admin. Code r. 481—426.2(105); Iowa Code 105.4', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.426.pdf', '2025-03-26'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:nec:2023')::uuid, 'IA', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Iowa state electrical code (Electrical Inspection Program). Applies statewide. Local amendments are allowed. Political subdivisions that do their own electrical inspections may amend the NEC. Amendments must be filed with the board and may not be less stringent than state minimums (Iowa Code 103.29(5)).', 'Iowa Admin. Code r. 481—404.3(103); Iowa Code ch. 103', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.404.pdf', '2025-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IA:ifc:2024')::uuid, 'IA', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'Iowa State Fire Code (Fire Control Administration). Applies statewide. A building in a jurisdiction that adopts and enforces its own fire code (any IFC or NFPA 1 edition, or the 1997 UFC) is deemed to comply (r. 481—280.11). Health care facilities are excepted.', 'Iowa Admin. Code r. 481—280.8(10A); Iowa Code 10A.511', 'https://www.legis.iowa.gov/docs/iac/chapter/11-19-2026.481.280.pdf', '2025-09-10'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:ibc:2018')::uuid, 'ID', md5('academykb:source:ibc-2018')::uuid, 'adopts', null, 'International Building Code (2018, with Idaho amendments). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Applies where a local government enforces building codes (it must adopt by ordinance), and on state and public buildings permitted by DOPL. Local amendments must be at least equivalent, and accessibility provisions may not be amended. Selected 2021 IBC mass-timber provisions are also adopted (IDAPA 24.39.30.600.02).', 'Idaho Code 39-4109, 39-4116; IDAPA 24.39.30.600.01', 'https://adminrules.idaho.gov/rules/current/24/243930.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:irc:2018')::uuid, 'ID', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'Idaho Residential Code (2018 IRC Parts I, II, III and IX, with Idaho amendments). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Local amendments are limited to Parts I, II, R301 and IX, plus the rest of Part III with good cause. Locals may not adopt IRC provisions the Board has not adopted. Fire sprinklers may not be required in one- and two-family dwellings (39-4116(3)). The IRC mechanical, fuel gas, plumbing and electrical parts are not adopted here.', 'Idaho Code 39-4109(1)(b), 39-4116; IDAPA 24.39.30.600.03', 'https://adminrules.idaho.gov/rules/current/24/243930.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:iebc:2018')::uuid, 'ID', md5('academykb:source:iebc-2018')::uuid, 'adopts', null, 'International Existing Building Code (2018). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Idaho Code 39-4116(2) does not list the IEBC among the codes locals must adopt.', 'Idaho Code 39-4109(1)(d); IDAPA 24.39.30.600.04', 'https://adminrules.idaho.gov/rules/current/24/243930.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:iecc:2018')::uuid, 'ID', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'Idaho Energy Conservation Code - Commercial Provisions (2018 IECC with amendments). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed.', 'Idaho Code 39-4109(1)(c); chapter 97, title 39; IDAPA 24.39.30.600.05', 'https://adminrules.idaho.gov/rules/current/24/243930.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:iecc:2018')::uuid, 'ID', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'Idaho Energy Conservation Code - Residential Provisions (2018 IECC with amendments). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Locals may not adopt residential IECC provisions the Board has not adopted (39-4116(4)(b)). The statute names it the ''2018 Idaho energy conservation code''.', 'Idaho Code 39-4109(1)(c); IDAPA 24.39.30.600.06', 'https://adminrules.idaho.gov/rules/current/24/243930.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:imc:2018')::uuid, 'ID', md5('academykb:source:imc-2018')::uuid, 'adopts', null, 'Idaho Mechanical Code (2018 IMC with amendments). Applies statewide. The Idaho Mechanical Code also adopts 2018 IRC Parts V (Mechanical) and VI (Fuel Gas) for dwellings.', 'Idaho Code 54-5001; IDAPA 24.39.70.600.01', 'https://adminrules.idaho.gov/rules/current/24/243970.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:ifgc:2018')::uuid, 'ID', md5('academykb:source:ifgc-2018')::uuid, 'adopts', null, 'Idaho Mechanical Code - International Fuel Gas Code (2018 with amendments). Applies statewide.', 'Idaho Code 54-5001; IDAPA 24.39.70.600.02', 'https://adminrules.idaho.gov/rules/current/24/243970.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:upc:2015')::uuid, 'ID', md5('academykb:source:upc-2015')::uuid, 'adopts', null, 'Idaho State Plumbing Code (ISPC) (DOPL lists it as the ''2017 Idaho State Plumbing Code''). Applies statewide.', 'Idaho Code 54-2601; IDAPA 24.39.20.600', 'https://adminrules.idaho.gov/rules/current/24/243920.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:nec:2023')::uuid, 'ID', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Idaho Electrical Code (2023 NEC with amendments). Applies statewide. The rule section carries the date (4-4-25); this was not confirmed as the effective date of the 2023 NEC adoption.', 'Idaho Code 54-1001; IDAPA 24.39.10.600', 'https://adminrules.idaho.gov/rules/current/24/243910.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ID:ifc:2018')::uuid, 'ID', md5('academykb:source:ifc-2018')::uuid, 'adopts', null, 'International Fire Code (as adopted by the Idaho State Fire Marshal). Applies statewide. Minimum statewide standard. IDAPA 18.08.01 itself does not state the edition year. The 2018 edition comes from the DOPL ''Idaho Adopted Codes'' list.', 'Idaho Code 41-253; IDAPA 18.08.01', 'https://adminrules.idaho.gov/rules/current/18/180801.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IL:iecc:2024')::uuid, 'IL', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'Illinois Energy Conservation Code. Applies statewide. Applies to commercial (Subpart C) and residential (Subpart D) buildings statewide. Municipalities and CDB-funded projects may use the Illinois Stretch Energy Code (20 ILCS 3125/55). Local stringency rules (e.g., Chicago and home-rule units) not verified here.', '20 ILCS 3125/15 (Energy Efficient Building Act); 71 Ill. Adm. Code 600', 'https://cdb.illinois.gov/business/codes/illinois-energy-codes/illinois-energy-conservation-code.html', '2025-11-30'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IL:ibc:ibc-iebc-current-or-most-recent-preceding-edition-')::uuid, 'IL', md5('academykb:source:st:IL:ibc:ibc-iebc-current-or-most-recent-preceding-edition-')::uuid, 'adopts', null, 'IBC / IEBC (current or most recent preceding edition) for commercial buildings in jurisdictions without a building code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Applies to commercial buildings in jurisdictions that have not adopted a building code, and state-funded buildings (non-state buildings must be inspected by a qualified inspector). Local codes adopted after 1/1/25 must regulate structural design at least as stringently as the IBC/IEBC. No single edition is fixed by the state; the rule is current or most recent preceding edition.', '20 ILCS 3105/10.09-1 (Capital Development Board Act, as amended by P.A. 103-0510)', 'https://cdb.illinois.gov/business/codes/buildingcodesregulations.html', '2025-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IL:nec:nec-current-or-most-recent-preceding-edition-for-c')::uuid, 'IL', md5('academykb:source:st:IL:nec:nec-current-or-most-recent-preceding-edition-for-c')::uuid, 'adopts', null, 'NEC (current or most recent preceding edition) for commercial buildings in jurisdictions without a building code. Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Same applicability as the IBC entry; no fixed edition.', '20 ILCS 3105/10.09-1', 'https://cdb.illinois.gov/business/codes/buildingcodesregulations.html', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IL:irc:irc-under-the-illinois-residential-building-code-a')::uuid, 'IL', md5('academykb:source:st:IL:irc:irc-under-the-illinois-residential-building-code-a')::uuid, 'adopts', null, 'IRC under the Illinois Residential Building Code Act (jurisdictions without a building code). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Only in jurisdictions with no building code: new homes must follow the current IRC, or (if buyer and builder agree) the current or preceding IRC edition or a municipal/county residential code within 100 miles. Not enforced by a state inspection program. Local codes must be at least as stringent as the IRC for structural design from 1/1/25.', '815 ILCS 670/15', 'https://cdb.illinois.gov/business/codes/buildingcodesregulations.html', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:irc:2018')::uuid, 'IN', md5('academykb:source:irc-2018')::uuid, 'adopts', null, '2020 Indiana Residential Code. Residential. Applies statewide. Applies to Class 2 structures (one- and two-family dwellings, townhouses) and their accessory structures; residential energy provisions are in this code.', '675 IAC 14-4.4', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2019-12-26'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:ibc:2012')::uuid, 'IN', md5('academykb:source:ibc-2012')::uuid, 'adopts', null, '2014 Indiana Building Code. Commercial and other non-residential buildings. Applies statewide. Applies to Class 1 structures. A 2026 Indiana Building Code (675 IAC 13-2.7, based on the 2024 IBC) is in rulemaking and not yet effective.', '675 IAC 13-2.6', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2014-12-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:ipc:2006')::uuid, 'IN', md5('academykb:source:ipc-2006')::uuid, 'adopts', null, '2012 Indiana Plumbing Code. Applies statewide.', '675 IAC 16-1.4', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2012-12-24'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:imc:2012')::uuid, 'IN', md5('academykb:source:imc-2012')::uuid, 'adopts', null, '2014 Indiana Mechanical Code. Commercial and other non-residential buildings. Applies statewide. Mechanical requirements for one- and two-family dwellings are in the Indiana Residential Code.', '675 IAC 18-1.6', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2014-12-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:ifgc:2012')::uuid, 'IN', md5('academykb:source:ifgc-2012')::uuid, 'adopts', null, '2014 Indiana Fuel Gas Code. Applies statewide.', '675 IAC 25-3', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2014-12-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:ifc:2012')::uuid, 'IN', md5('academykb:source:ifc-2012')::uuid, 'adopts', null, '2014 Indiana Fire Code. Applies statewide. A new Indiana Fire Code update is in rulemaking (not yet effective).', '675 IAC 22-2.5', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2014-12-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:ashrae_90_1:2007')::uuid, 'IN', md5('academykb:source:ashrae_90_1-2007')::uuid, 'adopts', null, '2010 Indiana Energy Conservation Code. Commercial and other non-residential buildings. Applies statewide. Commercial energy code (ASHRAE 90.1-2007). Residential energy requirements are in the 2020 Indiana Residential Code.', '675 IAC 19-4', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', '2010-05-06'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:IN:nec:indiana-electrical-code-2009-edition-in-effect-unt')::uuid, 'IN', md5('academykb:source:st:IN:nec:indiana-electrical-code-2009-edition-in-effect-unt')::uuid, 'adopts', null, 'Indiana Electrical Code (2009 Edition in effect until replaced by 2026 Edition). Applies statewide. The 2009 Indiana Electrical Code adopts the 2008 NEC. The Commission adopted the Indiana Electrical Code, 2026 Edition (2023 NEC, LSA #26-62) as a final rule on Aug. 4, 2026; it takes effect 30 days after filing with the Indiana Register.', '675 IAC 17-1.8 (to be replaced by 675 IAC 17-1.9)', 'https://www.in.gov/dhs/fire-and-building-safety/fpbsc-rules/', null, null, true, '{}'::text[], 'pending_review', null, 'Could not confirm whether the 2026 Indiana Electrical Code (2023 NEC) has been filed and taken effect as of 2026-11-22; the official docket (last updated Aug. 18, 2026) shows the effective date as TBD, and the Indiana Register site could not be read. If not yet effective, the 2009 Indiana Electrical Code (2008 NEC, eff. 8/26/2009) remains in force.'),
  (md5('academykb:adoption:st:KS:ifc:2006')::uuid, 'KS', md5('academykb:source:ifc-2006')::uuid, 'adopts', null, 'Kansas Fire Prevention Code (K.A.R. 22-1-3), adopting the International Fire Code. Commercial and other non-residential buildings. Applies statewide. The State Fire Marshal''s statewide fire code. It is the 2006 IFC with some chapters excluded, and that is still the authenticated current text. The regulation was last amended Feb. 4, 2011, and that amendment''s effective date is not shown separately, so effective_date is null. It is part of the Kansas Fire Prevention Code (K.A.R. 22-1-3), which by statute has ''uniform force and effect throughout the state'', and municipalities may not enact inconsistent rules (K.S.A. 31-134(b)). The State Fire Marshal''s rules do not reach buildings used wholly as dwellings for no more than two families (K.S.A. 31-133).', 'K.A.R. 22-1-3; K.S.A. 31-133, 31-134', 'https://rules.ks.gov/api/policy-library-public/collections/0ae1e448-f5a1-4e09-9d6d-a488ac7c284a/policies/1ebc02f6-abe2-4127-9e00-a266d7216853/document/390df88f-493d-4a76-b770-67ec7299c0a3', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KS:ibc:2006')::uuid, 'KS', md5('academykb:source:ibc-2006')::uuid, 'adopts', null, 'International Building Code as adopted by reference in the Kansas Fire Prevention Code. Commercial and other non-residential buildings. Applies statewide. Adopted by the State Fire Marshal as part of the fire prevention code and applied to buildings under the Fire Marshal''s authority, for example school construction (K.A.R. 22-18-3). This is not a general statewide building code for private construction, which is adopted locally. It is part of the Kansas Fire Prevention Code (K.A.R. 22-1-3), which by statute has ''uniform force and effect throughout the state'', and municipalities may not enact inconsistent rules (K.S.A. 31-134(b)). The State Fire Marshal''s rules do not reach buildings used wholly as dwellings for no more than two families (K.S.A. 31-133).', 'K.A.R. 22-1-3; K.S.A. 31-133, 31-134', 'https://rules.ks.gov/api/policy-library-public/collections/0ae1e448-f5a1-4e09-9d6d-a488ac7c284a/policies/1ebc02f6-abe2-4127-9e00-a266d7216853/document/390df88f-493d-4a76-b770-67ec7299c0a3', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KS:nec:2008')::uuid, 'KS', md5('academykb:source:nec-2008')::uuid, 'adopts', null, 'National Electrical Code (NFPA 70) as adopted by reference in the Kansas Fire Prevention Code. Commercial and other non-residential buildings. Applies statewide. Adopted by the State Fire Marshal as part of the fire prevention code, for example for school building wiring (K.A.R. 22-18-3). This is not a general statewide electrical code; cities and counties adopt their own. It is part of the Kansas Fire Prevention Code (K.A.R. 22-1-3), which by statute has ''uniform force and effect throughout the state'', and municipalities may not enact inconsistent rules (K.S.A. 31-134(b)). The State Fire Marshal''s rules do not reach buildings used wholly as dwellings for no more than two families (K.S.A. 31-133).', 'K.A.R. 22-1-3; K.S.A. 31-133, 31-134', 'https://rules.ks.gov/api/policy-library-public/collections/0ae1e448-f5a1-4e09-9d6d-a488ac7c284a/policies/1ebc02f6-abe2-4127-9e00-a266d7216853/document/390df88f-493d-4a76-b770-67ec7299c0a3', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:irc:2015')::uuid, 'KY', md5('academykb:source:irc-2015')::uuid, 'adopts', null, '2018 Kentucky Residential Code. Residential. Applies statewide. One- and two-family dwellings and townhouses. Effective date is that of the current version of 815 KAR 7:125 (incorporating the 2018 KRC, Third Edition, August 2024). Permits/inspections for single-family homes only where required by local ordinance.', '815 KAR 7:125', 'https://apps.legislature.ky.gov/law/kar/titles/815/007/125/', '2024-12-03'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:ibc:2015')::uuid, 'KY', md5('academykb:source:ibc-2015')::uuid, 'adopts', null, '2018 Kentucky Building Code. Commercial and other non-residential buildings. Applies statewide. All buildings other than one- and two-family dwellings, townhouses and manufactured homes (includes multifamily). Effective date is that of the current version of 815 KAR 7:120 (incorporating the 2018 KBC, Fourth Edition, February 2024).', '815 KAR 7:120', 'https://apps.legislature.ky.gov/law/kar/titles/815/007/120/', '2024-12-03'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:imc:2015')::uuid, 'KY', md5('academykb:source:imc-2015')::uuid, 'adopts', null, '2015 International Mechanical Code (as referenced by the Kentucky Building Code). Commercial and other non-residential buildings. Applies statewide.', '815 KAR 7:120 (Kentucky Building Code)', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:iebc:2015')::uuid, 'KY', md5('academykb:source:iebc-2015')::uuid, 'adopts', null, '2015 International Existing Building Code (as referenced by the Kentucky Building Code). Commercial and other non-residential buildings. Applies statewide.', '815 KAR 7:120 (Kentucky Building Code)', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:iecc:2012')::uuid, 'KY', md5('academykb:source:iecc-2012')::uuid, 'adopts', null, '2012 International Energy Conservation Code (commercial). Commercial and other non-residential buildings. Applies statewide. Commercial energy code.', '815 KAR 7:120 (Kentucky Building Code)', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:iecc:2009')::uuid, 'KY', md5('academykb:source:iecc-2009')::uuid, 'adopts', null, '2009 International Energy Conservation Code (residential). Residential. Applies statewide. Residential energy code.', '815 KAR 7:125 (Kentucky Residential Code)', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:nfpa54:2012')::uuid, 'KY', md5('academykb:source:nfpa54-2012')::uuid, 'adopts', null, 'NFPA 54 National Fuel Gas Code. Applies statewide. Family value ''nfpa54'' is not in the brief''s enum; this is the NFPA 54 fuel gas code.', '815 KAR 7:120 / 7:125 (referenced standard)', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:nec:2023')::uuid, 'KY', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'NFPA 70 National Electrical Code (as incorporated in the KBC and KRC). Applies statewide. Under the 2018 KRC, several 2023 NEC provisions were delayed; 210.52(C), 230.67 and 314.27(C) became enforceable July 15, 2026, while GFCI provisions 210.8(A) and 210.8(D)(8)-(11) remain delayed. DHBC formed a task force in March 2026 to review the 2026 NEC.', '815 KAR 7:120 and 815 KAR 7:125', 'https://dhbc.ky.gov/Documents/Find%20Currently%20Enforced%20Code.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:nfpa1:2018')::uuid, 'KY', md5('academykb:source:nfpa1-2018')::uuid, 'adopts', null, 'Kentucky Standards of Safety (NFPA 1, Uniform Fire Code). Applies statewide. State fire code for existing buildings (enforced by the State Fire Marshal). For new construction the 2015 IFC applies only where specifically referenced by the KBC.', '815 KAR 10:060', 'https://apps.legislature.ky.gov/law/kar/titles/815/010/060/', '2023-09-26'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:KY:state_plumbing:kentucky-state-plumbing-law-regulations-code')::uuid, 'KY', md5('academykb:source:st:KY:state_plumbing:kentucky-state-plumbing-law-regulations-code')::uuid, 'adopts', null, 'Kentucky State Plumbing Law, Regulations & Code. Applies statewide. State-written plumbing code applied statewide by the Division of Plumbing.', 'KRS Chapter 318; 815 KAR Chapter 20', 'https://apps.legislature.ky.gov/law/kar/titles/815/020/010/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:ibc:2021')::uuid, 'LA', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Building Code, 2021 edition with Louisiana amendments. Commercial and other non-residential buildings. Applies statewide.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:iebc:2021')::uuid, 'LA', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Existing Building Code, 2021 edition with Louisiana amendments. Commercial and other non-residential buildings. Applies statewide. For structures permitted on or after Jan. 1, 2026, the fire marshal uses the IEBC (not NFPA 101''s existing-building chapter) when addressing serious life hazards in existing buildings (La. R.S. 40:1578.6).', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:irc:2021')::uuid, 'LA', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Residential Code, 2021 edition with Louisiana amendments. Residential. Applies statewide. Mandatory for new construction, reconstruction, additions to homes built to the IRC, and extensive alterations; IRC electrical part excluded (NEC governs); fire sprinklers in one- and two-family dwellings may not be required.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:imc:2021')::uuid, 'LA', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Mechanical Code, 2021 edition with Louisiana amendments. Applies statewide.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:ifgc:2021')::uuid, 'LA', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Fuel Gas Code, 2021 edition with Louisiana amendments. Applies statewide.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:ipc:2021')::uuid, 'LA', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Plumbing Code, 2021 edition with Louisiana amendments. Applies statewide. The IPC replaced the Louisiana State Plumbing Code on 01/01/2016.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:iecc:2021')::uuid, 'LA', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - International Energy Conservation Code, 2021 edition with Louisiana amendments. Applies statewide. IECC 2021 became effective July 1, 2023, later than the other 2021 ICC codes.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:LA:nec:2020')::uuid, 'LA', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'Louisiana State Uniform Construction Code - National Electrical Code, 2020 edition. Applies statewide.', 'La. R.S. 40:1730.28; LAC Title 17, Part I (Louisiana State Uniform Construction Code)', 'https://luccc.louisiana.gov/wp-content/uploads/2025/11/LSUCCC_Louisiana-Construction-Code-Information.pdf', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:ibc:2021')::uuid, 'MA', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Massachusetts State Building Code, Tenth Edition, Base Volume (780 CMR). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Applies to all buildings other than those under the Residential Volume. Ninth Edition concurrency ended June 30, 2025. Cities and towns cannot amend 780 CMR on their own; under M.G.L. c. 143, s. 98 a city or town may ask the BBRS to adopt more restrictive rules for it.', '780 CMR; M.G.L. c. 143, ss. 93-100', 'https://www.sec.state.ma.us/reg_pub/pdf/700/780001.pdf', '2024-10-11'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:irc:2021')::uuid, 'MA', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Massachusetts Residential Code, Tenth Edition, Residential Volume (780 CMR 51.00). Residential. Applies statewide. Local governments may not amend it. Detached one- and two-family dwellings and townhouses not more than three stories above grade plane, plus owner-occupied lodging houses with five or fewer guestrooms. Cities and towns cannot amend 780 CMR on their own; under M.G.L. c. 143, s. 98 a city or town may ask the BBRS to adopt more restrictive rules for it.', '780 CMR 51.00; M.G.L. c. 143, ss. 93-100', 'https://www.sec.state.ma.us/reg_pub/pdf/700/780051.pdf', '2024-10-11'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:iebc:2021')::uuid, 'MA', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, '780 CMR 34.00: Existing Building Code. Applies statewide. Local governments may not amend it.', '780 CMR 34.00', 'https://www.sec.state.ma.us/reg_pub/pdf/700/780001.pdf', '2024-10-11'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:imc:2021')::uuid, 'MA', md5('academykb:source:imc-2021')::uuid, 'adopts', null, '780 CMR (IMC 2021 adoption, sec. 101.4.2). Applies statewide. Local governments may not amend it. Does not apply to work under the specialized codes (e.g., sheet metal work under M.G.L. c. 112, s. 237).', '780 CMR 1.00, sec. 101.4.2', 'https://www.sec.state.ma.us/reg_pub/pdf/700/780001.pdf', '2024-10-11'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:iecc:2021')::uuid, 'MA', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Massachusetts base energy code: 780 CMR 13.00 (commercial) and 780 CMR 51.00 Chapter 11 (residential). Applies statewide. Base energy code statewide; where a municipality has adopted the Stretch or Municipal Opt-in Specialized energy code, 225 CMR 22.00 (low-rise residential) / 225 CMR 23.00 (commercial and other) apply instead. Commercial path also allows ASHRAE 90.1 (780 CMR 13.00, C401.2.2).', '780 CMR 13.00; 780 CMR 51.00 ch. R11', 'https://www.sec.state.ma.us/reg_pub/pdf/700/780051.pdf', '2024-10-11'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:state_plumbing:uniform-state-plumbing-code-248-cmr-10-00')::uuid, 'MA', md5('academykb:source:st:MA:state_plumbing:uniform-state-plumbing-code-248-cmr-10-00')::uuid, 'adopts', null, 'Uniform State Plumbing Code (248 CMR 10.00). Applies statewide. State-written plumbing code; 780 CMR points all IPC/IFGC references to 248 CMR. Gas fitting is under 248 CMR 4.00/5.00 (Massachusetts Fuel Gas Code, amending NFPA 54).', '248 CMR (Board of State Examiners of Plumbers and Gas Fitters)', 'https://www.mass.gov/regulations/248-CMR-10', null, null, true, '{}'::text[], 'pending_review', null, 'mass.gov (where the current 248 CMR 10.00 text and its effective date are posted) returned 403 to automated access; existence and statewide role confirmed via 780 CMR 1.00, but current version/effective date not confirmed from official text.'),
  (md5('academykb:adoption:st:MA:nec:2026')::uuid, 'MA', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'Massachusetts Electrical Code (527 CMR 12.00). Applies statewide. Rule 7: effective on all installations for which a permit has been granted subsequent to April 24, 2026.', '527 CMR 12.00 (Board of Fire Prevention Regulations)', 'https://www.sec.state.ma.us/reg_pub/pdf/500/527012.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MA:nfpa1:2021')::uuid, 'MA', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, 'Massachusetts Comprehensive Fire Safety Code (527 CMR 1.00). Applies statewide. Enforced by the head of the local fire department; 780 CMR may reference specific IFC 2021 sections but 527 CMR 1.00 governs fire prevention.', '527 CMR 1.00 (Board of Fire Prevention Regulations)', 'https://www.sec.state.ma.us/reg_pub/pdf/500/527001.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MD:ibc:2021')::uuid, 'MD', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Maryland Building Performance Standards (IBC as modified). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Local jurisdictions enforce and had to implement by May 29, 2024; local amendments allowed but may not weaken energy, residential sprinkler, or wind provisions (PS § 12-504). IBC plumbing, mechanical and electrical chapters are excluded from the MBPS.', 'COMAR 09.12.51 (Maryland Building Performance Standards); Md. Code, Public Safety § 12-503', 'https://dsd.maryland.gov/regulations/Pages/09.12.51.04.aspx', '2023-05-29'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MD:irc:2021')::uuid, 'MD', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Maryland Building Performance Standards (IRC as modified). Residential. Applies statewide. Local amendments are allowed. Local amendments allowed except they may not weaken energy, townhouse/one- and two-family sprinkler, or wind provisions (PS § 12-504). IRC plumbing and electrical chapters are excluded from the MBPS.', 'COMAR 09.12.51 (Maryland Building Performance Standards); Md. Code, Public Safety § 12-503', 'https://dsd.maryland.gov/regulations/Pages/09.12.51.04.aspx', '2023-05-29'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MD:iecc:2021')::uuid, 'MD', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Maryland Building Performance Standards (IECC as modified). Applies statewide. Local amendments are allowed. Local amendments may not weaken energy conservation provisions (PS § 12-504(a)(1)(ii)).', 'COMAR 09.12.51 (Maryland Building Performance Standards); Md. Code, Public Safety § 12-503', 'https://dsd.maryland.gov/regulations/Pages/09.12.51.04.aspx', '2023-05-29'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MD:nfpa1:2024')::uuid, 'MD', md5('academykb:source:nfpa1-2024')::uuid, 'adopts', null, 'Maryland State Fire Prevention Code (NFPA 1 and NFPA 101, 2024 editions, as amended). Applies statewide. Enforced by the State Fire Marshal or authorized local fire officials; applies to new and existing buildings. Also incorporates NFPA 101 Life Safety Code (2024 Edition).', 'COMAR 29.06.01; Md. Code, Public Safety §§ 6-206, 6-501', 'https://dsd.maryland.gov/regulations/Pages/29.06.01.06.aspx', '2025-06-23'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MD:ipc:maryland-state-plumbing-code-comar-09-20-01')::uuid, 'MD', md5('academykb:source:st:MD:ipc:maryland-state-plumbing-code-comar-09-20-01')::uuid, 'adopts', null, 'Maryland State Plumbing Code (COMAR 09.20.01). Applies statewide. The State Board of Plumbing adopts ''the most recent version'' of the IPC, IRC, IFGC, NFPA 54 and NFPA 58; MBPS refers users to the local plumbing code and this state plumbing code.', 'COMAR 09.20.01.01; Md. Code, Bus. Occ. & Prof. §§ 12-101(p), 12-205(a)', 'https://dsd.maryland.gov/regulations/Pages/09.20.01.01.aspx', null, null, true, '{}'::text[], 'pending_review', null, 'Rule adopts the ''most recent version'' with no edition year; the edition actually enforced and local adoption/amendment rules are not stated on an official page reviewed.'),
  (md5('academykb:adoption:st:MD:nec:national-electrical-code-as-adopted-under-md-code-')::uuid, 'MD', md5('academykb:source:st:MD:nec:national-electrical-code-as-adopted-under-md-code-')::uuid, 'adopts', null, 'National Electrical Code as adopted under Md. Code, Public Safety Title 12, Subtitle 6. Electrical work is outside the MBPS; MBPS directs users to the local electrical code and the NEC as adopted and enforced by the State Fire Marshal, authorized fire officials, or building officials.', 'Md. Code, Public Safety Title 12, Subtitle 6 (§ 12-603)', 'https://dsd.maryland.gov/regulations/Pages/09.12.51.04.aspx', null, null, true, '{}'::text[], 'pending_review', null, 'No official current source found stating the NEC edition; a Labor code matrix (undated/possibly stale) lists 2017 NEC for the State Fire Marshal and 2020 NEC in COMAR 09.12.50 - conflicting/stale, not used.'),
  (md5('academykb:adoption:st:ME:ibc:2021')::uuid, 'ME', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Maine Uniform Building and Energy Code (MUBEC) - Commercial Building Code of Maine. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. MUBEC applies to all construction statewide, but local enforcement (permits/inspections) is required only in municipalities over 4,000 residents; smaller towns may choose to enforce it and may not adopt any other building code. Exempt: log homes, manufactured housing, post-and-beam/timber frame, and crop storage warehouses/silos (10 M.R.S. 9724(5)(A)).', '16-642 C.M.R. ch. 3; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C003.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:irc:2021')::uuid, 'ME', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'MUBEC - Residential Building Code for One- and Two-Family Dwellings. Residential. Applies statewide. Local governments may not amend it. MUBEC applies to all construction statewide, but local enforcement (permits/inspections) is required only in municipalities over 4,000 residents; smaller towns may choose to enforce it and may not adopt any other building code. Exempt: log homes, manufactured housing, post-and-beam/timber frame, and crop storage warehouses/silos (10 M.R.S. 9724(5)(A)).', '16-642 C.M.R. ch. 5; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C005.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:iebc:2021')::uuid, 'ME', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'MUBEC - Existing Building Code. Applies statewide. Local governments may not amend it. MUBEC applies to all construction statewide, but local enforcement (permits/inspections) is required only in municipalities over 4,000 residents; smaller towns may choose to enforce it and may not adopt any other building code. Exempt: log homes, manufactured housing, post-and-beam/timber frame, and crop storage warehouses/silos (10 M.R.S. 9724(5)(A)).', '16-642 C.M.R. ch. 4; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C004.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:iecc:2021')::uuid, 'ME', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'MUBEC - Energy Code. Applies statewide. Local governments may not amend it. MUBEC applies to all construction statewide, but local enforcement (permits/inspections) is required only in municipalities over 4,000 residents; smaller towns may choose to enforce it and may not adopt any other building code. Exempt: log homes, manufactured housing, post-and-beam/timber frame, and crop storage warehouses/silos (10 M.R.S. 9724(5)(A)). Commercial path also references ASHRAE 90.1-2019. Municipalities may opt into the MUBEC Stretch Code (Appendix NA), which is then mandatory there.', '16-642 C.M.R. ch. 6; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C006_0.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:ashrae_90_1:2019')::uuid, 'ME', md5('academykb:source:ashrae_90_1-2019')::uuid, 'adopts', null, 'MUBEC - ASHRAE 90.1 (commercial energy). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Listed among MUBEC-adopted standards (editions without addenda); applies to buildings other than low-rise residential.', '16-642 C.M.R. ch. 6; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/MUBEC%20Standards%20and%20Amendments.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:imc:2021')::uuid, 'ME', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'MUBEC - Mechanical Code. Applies statewide. Local governments may not amend it. MUBEC applies to all construction statewide, but local enforcement (permits/inspections) is required only in municipalities over 4,000 residents; smaller towns may choose to enforce it and may not adopt any other building code. Exempt: log homes, manufactured housing, post-and-beam/timber frame, and crop storage warehouses/silos (10 M.R.S. 9724(5)(A)).', '16-642 C.M.R. ch. 7; 10 M.R.S. ch. 1103', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C007.pdf', '2025-04-07'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:nec:2026')::uuid, 'ME', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'Maine Electrical Installation Standards (Electricians'' Examining Board Chapter 120). Applies statewide. Applies to electrical installations statewide, inspected by state electrical inspectors or local inspectors.', 'Electricians'' Examining Board rule Chapter 120 (Office of Professional and Occupational Regulation)', 'https://www.maine.gov/pfr/professionallicensing/professions/electricians', '2026-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ME:upc:2021')::uuid, 'ME', md5('academykb:source:upc-2021')::uuid, 'adopts', null, 'Maine Plumbing Code (Plumbers'' Examining Board Chapter 4, Installation Standards). Applies statewide. Statewide plumbing installation standard with Maine amendments; enforced by local plumbing inspectors.', '02-395 C.M.R. ch. 4; 32 M.R.S. §§ 3403-A, 3403-B', 'https://www.maine.gov/sos/rulemaking/agency-rules/department-professional-and-financial-regulation-rules#395', null, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:MI:ibc:2021')::uuid, 'MI', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, '2021 Michigan Building Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2025-04-09'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:irc:2015')::uuid, 'MI', md5('academykb:source:irc-2015')::uuid, 'adopts', null, '2015 Michigan Residential Code. Residential. Applies statewide. Local governments may not amend it. Includes residential energy, plumbing, mechanical and electrical requirements for 1-2 family dwellings. A 2021 IRC-based update (scheduled for Aug 29, 2025) is blocked by a July 7, 2025 Court of Claims stipulated order; the 2015 MRC remains in effect. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2016-02-08'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:iebc:2021')::uuid, 'MI', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, '2021 Michigan Rehabilitation Code. Applies statewide. Local governments may not amend it. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2025-04-09'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:imc:2021')::uuid, 'MI', md5('academykb:source:imc-2021')::uuid, 'adopts', null, '2021 Michigan Mechanical Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2024-03-12'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:ipc:2021')::uuid, 'MI', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, '2021 Michigan Plumbing Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2024-03-12'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:iecc:2021')::uuid, 'MI', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, '2021 Michigan Commercial Energy Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Commercial energy only; residential energy remains in the 2015 Michigan Residential Code (2021 residential energy update also blocked by the July 2025 court order). ASHRAE 90.1 edition not confirmed here. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2025-04-22'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MI:nec:2023')::uuid, 'MI', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Michigan Electrical Code (2023 NEC with Part 8 Electrical Code Rules). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Applies to buildings other than 1-2 family dwellings, whose electrical requirements are in the Michigan Residential Code. Model-code basis: MCL 125.1504(2) requires the state code to consist of the IRC, IBC, IMC, IPC, IEBC, IECC and NEC with amendments.', 'Stille-DeRossett-Hale Single State Construction Code Act, 1972 PA 230 (MCL 125.1501 et seq.), MCL 125.1504; Michigan Administrative Code construction code rules (LARA Bureau of Construction Codes)', 'https://www.michigan.gov/lara/bureau-list/bcc/rules-acts/codes/code-books', '2024-03-12'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MS:ifc:2024')::uuid, 'MS', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'Mississippi Fire Prevention Code (International Fire Code). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Mississippi Fire Prevention Code applies, under Miss. Code § 45-11-101, to public assembly buildings and new buildings 75 feet or taller, except in counties/municipalities that have adopted a fire prevention code no less stringent; enforced by the State Fire Marshal. The rule adopts the ''most current edition'' of the IFC and requires annual review of new editions.', 'Miss. Code § 45-11-101 et seq.; 19 Miss. Admin. Code Pt. 7, Ch. 7', 'https://www.mid.ms.gov/sfmo/fce/', '2024-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MS:ibc:2024')::uuid, 'MS', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'International Building Code (as adopted by the State Fire Marshal). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Mississippi Fire Prevention Code applies, under Miss. Code § 45-11-101, to public assembly buildings and new buildings 75 feet or taller, except in counties/municipalities that have adopted a fire prevention code no less stringent; enforced by the State Fire Marshal. The IBC is used by the State Fire Marshal where it applies to or affects IFC application; this is not a general statewide building code.', 'Miss. Code § 45-11-101 et seq.; 19 Miss. Admin. Code Pt. 7, Ch. 7', 'https://www.mid.ms.gov/sfmo/fce/', '2024-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MS:irc:state-uniform-construction-code-international-resi')::uuid, 'MS', md5('academykb:source:st:MS:irc:state-uniform-construction-code-international-resi')::uuid, 'adopts', null, 'State Uniform Construction Code - International Residential Code (as adopted by the Mississippi Building Codes Council). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Local option: counties/municipalities that did not opt out must adopt one of the last three MBCC-adopted editions as minimum codes.', 'Miss. Code § 17-2-1 et seq.', 'https://www.mid.ms.gov/sfmo/mississippi-uniform-building-codes/', null, null, true, '{}'::text[], 'pending_review', null, 'Could not locate an official Mississippi Building Codes Council adoption record or current admin-code text showing which IRC/IBC/IPC/IMC/IFGC/IECC editions the Council has adopted (secondary sources cite 2018 editions adopted Dec. 2019).'),
  (md5('academykb:adoption:st:MT:ibc:2024')::uuid, 'MT', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'Montana State Building Code - International Building Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Enforced by the state outside certified local jurisdictions. Certified city/county/town programs may enforce only codes adopted by the Building Codes Program and may not be more stringent (MCA 50-60-301(2)).', 'ARM 24.301.131; MCA 50-60-203', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:irc:2024')::uuid, 'MT', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'Montana State Building Code - International Residential Code. Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies to residential buildings of fewer than five units only where a county, city or town has made the state code applicable (MCA 50-60-102). Certified city/county/town programs may enforce only codes adopted by the Building Codes Program and may not be more stringent (MCA 50-60-301(2)).', 'ARM 24.301.154; MCA 50-60-102', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:iebc:2024')::uuid, 'MT', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'International Existing Building Code. Applies statewide. Local governments may not amend it. The proposed rule text says the IEBC ''may be used as an alternate prescriptive method'' for work on existing buildings.', 'ARM 24.301.171', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:iecc:2024')::uuid, 'MT', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'Montana energy code - International Energy Conservation Code. Applies statewide. Local governments may not amend it. Residential energy provisions apply statewide. For homes with fewer than five units outside local jurisdictions, they are enforced through builder self-certification (MCA 50-60-102(5)). Local governments may only add voluntary incentive-based standards. (''Septemeber'' is a typo on the source page.)', 'ARM 24.301.161; MCA 50-60-102(5)', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:imc:2024')::uuid, 'MT', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'International Mechanical Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Certified city/county/town programs may enforce only codes adopted by the Building Codes Program and may not be more stringent (MCA 50-60-301(2)).', 'ARM 24.301.172', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:ifgc:2024')::uuid, 'MT', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'International Fuel Gas Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Certified city/county/town programs may enforce only codes adopted by the Building Codes Program and may not be more stringent (MCA 50-60-301(2)).', 'ARM 24.301.173', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:upc:2024')::uuid, 'MT', md5('academykb:source:upc-2024')::uuid, 'adopts', null, 'Uniform Plumbing Code (Montana amendments). Applies statewide. Local governments may not amend it. Montana adopts the UPC, not the IPC. Minimum plumbing fixtures are set in ARM 24.301.351.', 'ARM 24.301.301', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:nec:2023')::uuid, 'MT', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'National Electrical Code (Montana amendments). Applies statewide. Local governments may not amend it. The NEC edition did not change (2023), but the DLI page lists September 26, 2026 as its effective date with the 2026 rule package. Not confirmed: whether the state electrical code applies to small residential work outside local jurisdictions despite MCA 50-60-102(1)(a).', 'ARM 24.301.401', 'https://bsd.dli.mt.gov/building-codes-permits/current-codes', '2026-09-26'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:MT:ifc:2021')::uuid, 'MT', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'International Fire Code (as adopted by the State Fire Marshal / DOJ Fire Prevention and Investigation Section). Applies statewide. Adopted by the Department of Justice, not DLI. Where the IFC conflicts with the DLI building code on construction standards, the building code controls. The adoption notice is dated 3/10/23 in the MAR; no effective date was captured.', 'ARM 23.12.601 (MAR Notice No. 23-12-266)', 'https://dojmt.gov/wp-content/uploads/23-12-266adp-arm.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:ibc:2015')::uuid, 'NC', md5('academykb:source:ibc-2015')::uuid, 'adopts', null, '2018 North Carolina Building Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:irc:2015')::uuid, 'NC', md5('academykb:source:irc-2015')::uuid, 'adopts', null, '2018 North Carolina Residential Code. Residential. Applies statewide. Local governments may not amend it. One- and two-family dwellings and townhouses. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:iebc:2015')::uuid, 'NC', md5('academykb:source:iebc-2015')::uuid, 'adopts', null, '2018 North Carolina Existing Building Code. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:ipc:2015')::uuid, 'NC', md5('academykb:source:ipc-2015')::uuid, 'adopts', null, '2018 North Carolina Plumbing Code. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:imc:2015')::uuid, 'NC', md5('academykb:source:imc-2015')::uuid, 'adopts', null, '2018 North Carolina Mechanical Code. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:ifgc:2015')::uuid, 'NC', md5('academykb:source:ifgc-2015')::uuid, 'adopts', null, '2018 North Carolina Fuel Gas Code. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:ifc:2015')::uuid, 'NC', md5('academykb:source:ifc-2015')::uuid, 'adopts', null, '2018 North Carolina Fire Code. Applies statewide. Local amendments are allowed. Local governments may adopt a fire prevention code, but it must be approved by the Building Code Council and may not add requirements for NC Residential Code dwellings beyond the Residential Code (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:iecc:2015')::uuid, 'NC', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, '2018 North Carolina Energy Conservation Code. Applies statewide. Local governments may not amend it. Local codes are not effective unless approved by the responsible Code Council (G.S. 143-138(e)).', 'N.C. Gen. Stat. § 143-138 (North Carolina State Building Code)', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2019-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NC:nec:2020')::uuid, 'NC', md5('academykb:source:nec-2020')::uuid, 'adopts', null, '2020 North Carolina Electrical Code (NEC with NC amendments). Applies statewide. Local governments may not amend it. The 2023 North Carolina Electrical Code is part of the 2024 Code package whose effective date is not yet set.', 'N.C. Gen. Stat. § 143-138', 'https://www.ncosfm.gov/codes/codes-current-and-past', '2021-11-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:ibc:2024')::uuid, 'ND', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Building Code). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Mandatory where a city, township or county elects to enforce a building code; also applies to state and local government buildings and public and private schools statewide (N.D. Admin. Code 108-01-01-04). No appendices adopted.', 'N.D.C.C. ch. 54-21.3; N.D. Admin. Code art. 108-01', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:irc:2024')::uuid, 'ND', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Residential Code). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Applies only where a local government elects to enforce a building code. State law bars requiring fire sprinklers in single-family and two-unit dwellings (N.D.C.C. 54-21.3-03(4)). Modular homes placed anywhere in the state must comply with the state building code.', 'N.D.C.C. ch. 54-21.3; N.D. Admin. Code art. 108-01', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:imc:2024')::uuid, 'ND', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Mechanical Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Part of the State Building Code; enforced only where locals elect to enforce.', 'N.D.C.C. 54-21.3-03; N.D. Admin. Code art. 108-01', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:ifgc:2024')::uuid, 'ND', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Fuel Gas Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Part of the State Building Code; enforced only where locals elect to enforce.', 'N.D.C.C. 54-21.3-03; N.D. Admin. Code art. 108-01', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:iecc:2024')::uuid, 'ND', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Energy Conservation Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Included in the 2026 State Building Code book with state amendments; N.D.C.C. 54-21.3-03 itself names only the IBC, IRC, IMC and IFGC. Enforced only where locals elect to enforce.', 'N.D. Admin. Code art. 108-01 (State Building Code as adopted by eligible jurisdictions)', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:iebc:2024')::uuid, 'ND', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'North Dakota State Building Code (International Existing Building Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Included in the 2026 State Building Code book; enforced only where locals elect to enforce.', 'N.D. Admin. Code art. 108-01 (State Building Code as adopted by eligible jurisdictions)', 'https://www.commerce.nd.gov/community-services/building-codes', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:nec:2026')::uuid, 'ND', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'North Dakota Electrical Wiring Standards (NFPA 70, 2026 edition). Applies statewide. State Electrical Board standards based on the 2026 NEC (first printing 2025) with state amendments; NFPA 101 2024 also referenced. Exempt from the State Building Code chapter (N.D.C.C. 54-21.3-04).', 'N.D. Admin. Code title 24.1 (art. 24.1-02, 24.1-06); N.D.C.C. 43-09-05', 'https://ndlegis.gov/api/acdata/pdf/24.1-02-01.pdf', '2026-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:upc:2018')::uuid, 'ND', md5('academykb:source:upc-2018')::uuid, 'adopts', null, '2018 North Dakota Plumbing Code. Applies statewide. Adopted by the State Board of Plumbing; includes UPC chapters 1-4, 6-11 and 17 and appendices A, B, C, D, E, I and M plus chapter 62-03.1-03.', 'N.D. Admin. Code 62-03.1-01-01; N.D.C.C. 43-18-09', 'https://ndlegis.gov/api/acdata/pdf/62-03.1-01.pdf', '2020-04-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:ND:ifc:2021')::uuid, 'ND', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'North Dakota State Fire Code. Applies statewide. State Fire Marshal rules; 2021 IFC with state modifications. The State Building Code itself does not include the IFC, so local governments adopt fire codes separately.', 'N.D. Admin. Code 45-18-01-04; N.D.C.C. 18-01-04', 'https://ndlegis.gov/api/acdata/pdf/45-18-01.pdf', '2024-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:ibc:2018')::uuid, 'NE', md5('academykb:source:ibc-2018')::uuid, 'adopts', null, 'Nebraska state building code: International Building Code. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. IBC 2018, excluding section 101.4.3 and chapter 29 (plumbing). Part of the Nebraska state building code (Neb. Rev. Stat. 71-6403). It applies to state-owned buildings, in each county, city or village that adopts it, and in each one that has not adopted its own conforming code within two years after a state code update. It does not apply to construction on a farm or for farm purposes (71-6406(1)(b)). Local governments may adopt a code that ''conforms generally'', which allows amendments, newer editions and appendices, but not a prior edition (71-6406(2)-(3)). Nebraska law does not require the state to inspect or enforce this code for private construction.', 'Neb. Rev. Stat. 71-6403(1)(a), 71-6404, 71-6406', 'https://nebraskalegislature.gov/laws/statutes.php?statute=71-6403', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:irc:2018')::uuid, 'NE', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'Nebraska state building code: International Residential Code. Residential. Applies statewide. Local amendments are allowed. IRC 2018, excluding section R313 (residential fire sprinklers) and chapters 25 through 33 (plumbing). Part of the Nebraska state building code (Neb. Rev. Stat. 71-6403). It applies to state-owned buildings, in each county, city or village that adopts it, and in each one that has not adopted its own conforming code within two years after a state code update. It does not apply to construction on a farm or for farm purposes (71-6406(1)(b)). Local governments may adopt a code that ''conforms generally'', which allows amendments, newer editions and appendices, but not a prior edition (71-6406(2)-(3)). Nebraska law does not require the state to inspect or enforce this code for private construction.', 'Neb. Rev. Stat. 71-6403(1)(b), 71-6404, 71-6406', 'https://nebraskalegislature.gov/laws/statutes.php?statute=71-6403', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:iebc:2018')::uuid, 'NE', md5('academykb:source:iebc-2018')::uuid, 'adopts', null, 'Nebraska state building code: International Existing Building Code. Applies statewide. Local amendments are allowed. IEBC 2018, excluding section 809. Part of the Nebraska state building code (Neb. Rev. Stat. 71-6403). It applies to state-owned buildings, in each county, city or village that adopts it, and in each one that has not adopted its own conforming code within two years after a state code update. It does not apply to construction on a farm or for farm purposes (71-6406(1)(b)). Local governments may adopt a code that ''conforms generally'', which allows amendments, newer editions and appendices, but not a prior edition (71-6406(2)-(3)). Nebraska law does not require the state to inspect or enforce this code for private construction.', 'Neb. Rev. Stat. 71-6403(1)(c), 71-6404, 71-6406', 'https://nebraskalegislature.gov/laws/statutes.php?statute=71-6403', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:upc:2018')::uuid, 'NE', md5('academykb:source:upc-2018')::uuid, 'adopts', null, 'Nebraska state building code: Uniform Plumbing Code. Applies statewide. Local amendments are allowed. UPC 2018. Local governments may instead adopt their own plumbing code under their statutory code-adoption powers (71-6406(2)(d)). Part of the Nebraska state building code (Neb. Rev. Stat. 71-6403). It applies to state-owned buildings, in each county, city or village that adopts it, and in each one that has not adopted its own conforming code within two years after a state code update. It does not apply to construction on a farm or for farm purposes (71-6406(1)(b)). Local governments may adopt a code that ''conforms generally'', which allows amendments, newer editions and appendices, but not a prior edition (71-6406(2)-(3)). Nebraska law does not require the state to inspect or enforce this code for private construction.', 'Neb. Rev. Stat. 71-6403(1)(d), 71-6404, 71-6406', 'https://nebraskalegislature.gov/laws/statutes.php?statute=71-6403', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:iecc:2018')::uuid, 'NE', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'Nebraska Energy Code. Applies statewide. Local amendments are allowed. Applies to all new buildings, and to renovations of or additions to existing buildings, where construction began on or after July 1, 2020 (81-1614). Manufactured and modular homes, historic buildings and federal buildings are exempt (81-1615). Local governments may adopt an equivalent local energy code (81-1618). The Department of Water, Energy, and Environment and local code authorities enforce it.', 'Neb. Rev. Stat. 81-1608 to 81-1626 (definition 81-1609(9); applicability 81-1614; local codes 81-1618)', 'https://nebraskalegislature.gov/laws/statutes.php?statute=81-1609', '2020-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:nec:2023')::uuid, 'NE', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'National Electrical Code as the minimum standard under the State Electrical Act. Applies statewide. Local amendments are allowed. The State Electrical Board''s wiring rules must follow the 2023 NEC, but the 2017 NEC applies for sections 210.8(A), 210.8(A)(3), 210.8(A)(5), 230.67(A) and 230.85. State inspection does not apply where a county, city or village has its own wiring standards at least as strict, enforced by a certified electrical inspector (81-2125).', 'Neb. Rev. Stat. 81-2104(5) (State Electrical Act, 81-2101 to 81-2144)', 'https://nebraskalegislature.gov/laws/statutes.php?statute=81-2104', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NE:nfpa1:2012')::uuid, 'NE', md5('academykb:source:nfpa1-2012')::uuid, 'adopts', null, 'Nebraska State Fire Code (NFPA 1 and NFPA 101, 2012 editions, with Nebraska amendments). Commercial and other non-residential buildings. Applies statewide. The State Fire Marshal''s State Fire Code. By statute it must conform generally to NFPA 1 (2012) and NFPA 101 Life Safety Code (2012) ''not later than July 1, 2019''. It covers places where people congregate, exits, LP gas, hazardous materials and similar topics. The State Fire Marshal reviews plans and may delegate authority to local fire prevention personnel (81-502). The SFM website posts ''Nebraska Amendments to NFPA 1; 2012 Edition'' and ''Nebraska Amendments to NFPA 101; 2012 Edition''.', 'Neb. Rev. Stat. 81-503.01; 153 NAC', 'https://nebraskalegislature.gov/laws/statutes.php?statute=81-503.01', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NH:ibc:2024')::uuid, 'NH', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'New Hampshire State Building Code (IBC 2024). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:iebc:2024')::uuid, 'NH', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'New Hampshire State Building Code (IEBC 2024). Applies statewide. Local governments may not amend it.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:irc:2024')::uuid, 'NH', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'New Hampshire State Building Code (IRC 2024). Residential. Applies statewide. Local governments may not amend it.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:ipc:2024')::uuid, 'NH', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'New Hampshire State Building Code (IPC 2024). Applies statewide. Local governments may not amend it.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:imc:2024')::uuid, 'NH', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'New Hampshire State Building Code (IMC 2024). Applies statewide. Local governments may not amend it.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:iecc:2018')::uuid, 'NH', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'New Hampshire State Building Code (IECC 2018). Applies statewide. Local governments may not amend it. Energy code stays at the 2018 IECC even though the other I-codes moved to 2024.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:nec:2023')::uuid, 'NH', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'New Hampshire State Building Code (NEC 2023). Applies statewide. Local governments may not amend it. RSA 155-A:2, XI bars enforcing AFCI requirements beyond the 2014 NEC.', 'RSA 155-A:1, IV', 'https://gc.nh.gov/rsa/html/XII/155-A/155-A-1.htm', null, null, false, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NH:nfpa1:2024')::uuid, 'NH', md5('academykb:source:nfpa1-2024')::uuid, 'adopts', null, 'New Hampshire State Fire Code (NFPA 1 and NFPA 101). Applies statewide. State fire code also adopts NFPA 101 Life Safety Code, 2024 edition (''the Life Safety Code, NFPA 101, 2024 edition''). Source note lists ''2026, 104:1, eff. July 27, 2026.'' (likely the date of the 2024-edition update; not stated in the text).', 'RSA 153:1, VI-a', 'https://gc.nh.gov/rsa/html/XII/153/153-1.htm', null, null, true, '{}'::text[], 'pending_review', null, 'Edition read from current RSA text on gc.nh.gov in several consistent fetches, but the site could not be downloaded directly, so the quote is a short excerpt returned by a fetch tool and was not byte-checked. Spot-check the quote and confirm the effective date (likely 2026-07-01 for the 2024 I-codes; fire code act eff. 2026-07-27).'),
  (md5('academykb:adoption:st:NJ:ibc:2024')::uuid, 'NJ', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Building Subcode. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code.', 'N.J.A.C. 5:23-3.14', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:irc:2024')::uuid, 'NJ', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - One- and Two-Family Dwelling Subcode. Residential. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code.', 'N.J.A.C. 5:23-3.21', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:state_plumbing:2024')::uuid, 'NJ', md5('academykb:source:st:NJ:state_plumbing:new-jersey-uniform-construction-code-plumbing-subc')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Plumbing Subcode (National Standard Plumbing Code/2024). Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code. New Jersey uses the National Standard Plumbing Code (not IPC/UPC); references to the IPC in other subcodes are redirected to it.', 'N.J.A.C. 5:23-3.15', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:nec:2023')::uuid, 'NJ', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Electrical Subcode. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code. Includes NFPA Tentative Interim Amendments 70-23-1 through 70-23-13.', 'N.J.A.C. 5:23-3.16', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:iecc:2024')::uuid, 'NJ', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Energy Subcode. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code. Commercial provisions are amended so that ASHRAE 90.1 is the commercial compliance path (C401.2 amendments); ASHRAE 90.1 edition not separately confirmed here.', 'N.J.A.C. 5:23-3.18', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:imc:2024')::uuid, 'NJ', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Mechanical Subcode. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code.', 'N.J.A.C. 5:23-3.20', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:ifgc:2024')::uuid, 'NJ', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'New Jersey Uniform Construction Code - Fuel Gas Subcode. Applies statewide. Local governments may not amend it. Adopted via R.2026 d.086, effective August 17, 2026 (N.J.A.C. history note). DCA: six-month grace period; complete applications submitted by February 17, 2027 may still be reviewed under the previous code.', 'N.J.A.C. 5:23-3.22', 'https://www.nj.gov/dca/codes/codreg/pdf_regs/njac_5_23_3.pdf', '2026-08-17'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NJ:ifc:new-jersey-uniform-fire-code-ifc-new-jersey-editio')::uuid, 'NJ', md5('academykb:source:st:NJ:ifc:new-jersey-uniform-fire-code-ifc-new-jersey-editio')::uuid, 'adopts', null, 'New Jersey Uniform Fire Code (IFC New Jersey Edition). Applies statewide. The Uniform Fire Code (Division of Fire Safety) governs existing buildings/fire prevention; new construction fire protection is the UCC fire protection subcode (N.J.A.C. 5:23-3.17), assembled from the 2024-based building, mechanical, fuel gas and one- and two-family subcodes.', 'N.J.A.C. 5:70', 'https://www.nj.gov/dca/dfs/codes/', null, null, true, '{}'::text[], 'pending_review', null, 'DFS page lists 2018 IFC NJ Edition materials and a 2023 IFC-update rule proposal; current in-force IFC edition under N.J.A.C. 5:70 not confirmed from rule text.'),
  (md5('academykb:adoption:st:NM:ibc:2021')::uuid, 'NM', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, '2021 New Mexico Commercial Building Code (NMCBC). Commercial and other non-residential buildings. Applies statewide. Covers all buildings under CID jurisdiction except one- and two-family dwellings and townhouses up to three stories, which fall under 14.7.3 NMAC. Applied together with the commercial energy code, 14.7.9 NMAC.', '14.7.2 NMAC (Sections 60-13-9 and 60-13-44 NMSA 1978)', 'https://www.srca.nm.gov/parts/title14/14.007.0002.html', '2023-07-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:irc:2021')::uuid, 'NM', md5('academykb:source:irc-2021')::uuid, 'adopts', null, '2021 New Mexico Residential Building Code (NMRBC). Residential. Applies statewide. Covers detached one- and two-family dwellings and townhouses up to three stories with separate means of egress. Permits could be issued under either the old or the new code until December 14, 2023; after that date only this code may be used.', '14.7.3 NMAC', 'https://www.srca.nm.gov/parts/title14/14.007.0003.html', '2023-07-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:iebc:2021')::uuid, 'NM', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, '2021 New Mexico Existing Building Code (NMEBC). Commercial and other non-residential buildings. Applies statewide. Covers work on existing buildings, except one- and two-family dwellings and townhouses up to three stories.', '14.7.7 NMAC', 'https://www.srca.nm.gov/parts/title14/14.007.0007.html', '2023-07-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:iecc:2021')::uuid, 'NM', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, '2021 New Mexico Residential Energy Conservation Code. Residential. Applies statewide. Residential energy code. Permits could be issued under either the old or the new code until July 30, 2024; after that date only this code may be used. The CID page lists it as ''effective 7.30.24'', which is the end of that transition.', '14.7.6 NMAC', 'https://www.srca.nm.gov/parts/title14/14.007.0006.html', '2024-01-30'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:iecc:2021')::uuid, 'NM', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, '2021 New Mexico Commercial Energy Conservation Code. Commercial and other non-residential buildings. Applies statewide. Commercial energy code. Permits could be issued under either the old or the new code until July 30, 2024; after that date only this code may be used.', '14.7.9 NMAC', 'https://www.srca.nm.gov/parts/title14/14.007.0009.html', '2024-01-30'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:upc:2024')::uuid, 'NM', md5('academykb:source:upc-2024')::uuid, 'adopts', null, '2024 New Mexico Plumbing Code. Applies statewide. Replaced the 2021 New Mexico Plumbing Code (2021 UPC). Permits may be issued under either the 2021 or the 2024 code until January 1, 2027; after that date only the 2024 code may be used. The srca.nm.gov part page still shows the 2021 version, while the CID page links to the 2024 text.', '14.8.2 NMAC', 'https://www.rld.nm.gov/construction-industries/forms-and-applications/rules-laws-and-building-codes/', '2026-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:NM:umc:2024')::uuid, 'NM', md5('academykb:source:umc-2024')::uuid, 'adopts', null, '2024 New Mexico Mechanical Code. Applies statewide. Replaced the 2021 New Mexico Mechanical Code (2021 UMC). Permits may be issued under either code until January 1, 2027; after that date only the 2024 code may be used. Fuel gas piping is covered through the New Mexico plumbing and mechanical codes, not a separate IFGC adoption.', '14.9.2 NMAC', 'https://www.rld.nm.gov/construction-industries/forms-and-applications/rules-laws-and-building-codes/', '2026-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:NM:nec:2020')::uuid, 'NM', md5('academykb:source:nec-2020')::uuid, 'adopts', null, '2020 New Mexico Electrical Code. Applies statewide. Permits could be issued under either the old or the new code until September 28, 2023; after that date only this code may be used. As of 2026-11-22, the CID page still lists the 2020 New Mexico Electrical Code as current.', '14.10.4 NMAC (Section 60-13-9 NMSA 1978)', 'https://www.srca.nm.gov/parts/title14/14.010.0004.html', '2023-03-28'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NM:ifc:2021')::uuid, 'NM', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'New Mexico Fire Code (State Fire Marshal), 10.25.5 NMAC. Commercial and other non-residential buildings. Applies statewide. Issued by the State Fire Marshal (Department of Homeland Security and Emergency Management). Sets the state''s minimum fire requirements. It does not apply to detached one- and two-family dwellings or townhouses up to three stories built to the NM Residential Building Code, unless they are used as commercial properties. New construction must meet the CID building codes. The edition comes from the rule''s definitions, which show ''[ 2015 ] 2021 edition'' (the bracketed 2015 is struck text).', '10.25.5 NMAC', 'https://www.srca.nm.gov/parts/title10/10.025.0005.html', '2022-11-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NV:iecc:2024')::uuid, 'NV', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'International Energy Conservation Code as adopted by the Governor''s Office of Energy. Applies statewide. Local amendments are allowed. This is the statewide minimum. Local governments that have a building code must include it and enforce it, and they may adopt more stringent standards if they report them to the Director (NRS 701.220(4)). NAC 701.185 automatically adopts the most recently published IECC unless the Director gives notice that it is unsuitable for Nevada.', 'NRS 701.220; NAC 701.185', 'https://www.energy.nv.gov/programs/building-energy-codes/state-adoption-status/', '2024-08-18'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NV:ifc:2024')::uuid, 'NV', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'Nevada State Fire Marshal regulations (NAC chapter 477), adopting the International Fire Code. Applies statewide. Local amendments are allowed. The regulations apply throughout the State. However, outside state-owned or state-occupied buildings, the State Fire Marshal does not enforce them in counties of 100,000 or more people (Clark, Washoe) or in consolidated municipalities (Carson City) unless a local fire chief asks. Where state and local rules conflict, the more stringent rule applies (except on state property), and local governments may adopt more stringent codes (NAC 477.280). The same rule also adopts the 2024 IBC, IEBC, IWUIC, UMC and UPC as part of the Fire Marshal''s regulations.', 'NRS 477.030; NAC 477.281 and 477.283 as amended by LCB File No. R205-24', 'https://www.leg.state.nv.us/Register/2024Register/R205-24AP.pdf', '2026-02-27'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:irc:2024')::uuid, 'NY', md5('academykb:source:irc-2024')::uuid, 'adopts', null, '2025 Residential Code of New York State (RCNYS). Residential. Applies statewide. Effective date per DOS: ''The effective date of the 2025 NYS Uniform Code is December 31, 2025.'' Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1220; Executive Law Article 18', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:ibc:2024')::uuid, 'NY', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, '2025 Building Code of New York State (BCNYS). Commercial and other non-residential buildings. Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1221; Executive Law Article 18', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:ipc:2024')::uuid, 'NY', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, '2025 Plumbing Code of New York State (PCNYS). Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1222', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:imc:2024')::uuid, 'NY', md5('academykb:source:imc-2024')::uuid, 'adopts', null, '2025 Mechanical Code of New York State (MCNYS). Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1223', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:ifgc:2024')::uuid, 'NY', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, '2025 Fuel Gas Code of New York State (FGCNYS). Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1224', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:ifc:2024')::uuid, 'NY', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, '2025 Fire Code of New York State (FCNYS). Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1225', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:iebc:2024')::uuid, 'NY', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, '2025 Existing Building Code of New York State (EBCNYS). Applies statewide. Model edition basis per DOS: ''NYS specific code books which are based on the 2024 International Code Council books with New York modifications'' (dos.ny.gov/2026-01-nycrr-changes-2025-codes). New York City is governed by its own construction codes (not verified here).', '19 NYCRR Part 1227', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:iecc:2024')::uuid, 'NY', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, '2025 Energy Conservation Construction Code of New York State (ECCCNYS). Applies statewide. Residential provisions based on the 2024 IECC per DOS energy RIS: ''the “Residential Provisions” of the 2024 ECCCNYS based upon the most recent (2024) edition of the IECC (“2024 IECC”)'' (the proposal called the book ''2024 ECCCNYS''; adopted as 2025 ECCCNYS). All-electric new-building provisions (19 NYCRR 1240.6, Subpart 1229-2) are suspended by court order.', '19 NYCRR Part 1240; Energy Law Article 11', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:ashrae_90_1:2022')::uuid, 'NY', md5('academykb:source:ashrae_90_1-2022')::uuid, 'adopts', null, 'NYS ASHRAE 90.1-2025 (Energy Standard for Sites and Buildings Except Low-Rise Residential Buildings). Commercial and other non-residential buildings. Applies statewide. Adopted as ''NYS ASHRAE 90.1-2025'', effective December 31, 2025 with no transition period (dos.ny.gov/notice-adoption). The quoted RIS was for the proposal, which used the working name ''2024 NYS ASHRAE 90.1''.', '19 NYCRR Part 1240', 'https://dos.ny.gov/notice-adoption', '2025-12-31'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:NY:nec:national-electrical-code-nfpa-70-as-referenced-by-')::uuid, 'NY', md5('academykb:source:st:NY:nec:national-electrical-code-nfpa-70-as-referenced-by-')::uuid, 'adopts', null, 'National Electrical Code (NFPA 70), as referenced by the Uniform Code. Applies statewide. New York has no separate statewide electrical code adoption; NFPA 70 is incorporated by reference through the Uniform Code books. Some municipalities license electricians/inspect separately.', '19 NYCRR Parts 1219-1229 (by reference within the NYS code books)', 'https://dos.ny.gov/system/files/documents/2025/06/appendix-b-ris-uniform-code.pdf', null, null, true, '{}'::text[], 'pending_review', null, 'Official DOS sources confirm NFPA 70 is referenced, but no official page reviewed states which NEC edition the 2025 Uniform Code references.'),
  (md5('academykb:adoption:st:OH:ibc:2021')::uuid, 'OH', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Ohio Building Code (OBC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Applies to commercial buildings and residential buildings with more than three dwelling units; enforced by certified local building departments or the state Division of Industrial Compliance. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted. The 2021-IBC-based OBC dates from 3/1/2024 per the rule''s prior-effective-dates list.', 'Ohio Adm. Code 4101:1-1-01 to 4101:1-35; R.C. 3781.10', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:1-1-01', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:state_residential:2018')::uuid, 'OH', md5('academykb:source:st:OH:state_residential:residential-code-of-ohio-for-one-two-and-three-fam')::uuid, 'adopts', null, 'Residential Code of Ohio for One-, Two-, and Three-Family Dwellings (RCO). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Based on the 2018 IRC. The code is statewide, but plan review/permits/inspections apply only where a certified residential building department has jurisdiction (RCO 101.5). Local regulations conflicting with the RCO must be submitted to the Board of Building Standards.', 'Ohio Adm. Code 4101:8-1-01 et seq.; R.C. 3781.10', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:8-1-01', '2019-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:imc:2021')::uuid, 'OH', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Ohio Mechanical Code (OMC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. IMC 2021 with Chapter 11 (refrigeration) from the IMC 2024. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted.', 'Ohio Adm. Code 4101:2-1-01 to 4101:2-15', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:2-1-01', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:ipc:2021')::uuid, 'OH', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Ohio Plumbing Code (OPC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Residential (1-3 family) plumbing is governed by the RCO. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted.', 'Ohio Adm. Code 4101:3-1-01 to 4101:3-15', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:3-1-01', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:iecc:2021')::uuid, 'OH', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Ohio Building Code Chapter 13 / Chapter 35 (IECC 2021, commercial and residential provisions, as modified). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Applies to buildings under the OBC. 1-3 family dwellings use RCO Chapter 11 (2018 IRC-based, with OHBA alternative and IECC options) - see notes. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted.', 'Ohio Adm. Code 4101:1-13-01; 4101:1-35-01', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/1/4101$1-35-01_eff_10_15_25.pdf', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:ashrae_90_1:2019')::uuid, 'OH', md5('academykb:source:ashrae_90_1-2019')::uuid, 'adopts', null, 'ASHRAE 90.1-2019 (OBC Chapter 13 alternative). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. OBC 1301.1.1 permits IECC or ASHRAE 90.1 as listed in Chapter 35, with Ohio modifications in 1301.3. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted.', 'Ohio Adm. Code 4101:1-13-01; 4101:1-35-01', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/1/4101$1-35-01_eff_10_15_25.pdf', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:nec:2023')::uuid, 'OH', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'NFPA 70 National Electrical Code (as referenced by the Ohio Building Code). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Referenced standard for buildings under the OBC. RCO Chapter 44 (4101:8-44-01, eff. 4/15/2024) also lists NFPA 70 but the rule PDF text renders the edition as "70—1723" (strike-through/underline formatting), so the residential NEC edition is not recorded here. effective_date is the effective date of the current version of the rule shown on codes.ohio.gov, not necessarily the date the model-code edition was first adopted.', 'Ohio Adm. Code 4101:1-27-01; 4101:1-35-01', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/1/4101$1-35-01_eff_10_15_25.pdf', '2025-10-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OH:ifc:2021')::uuid, 'OH', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'Ohio Fire Code (OFC). Applies statewide. Adopted by the State Fire Marshal; IFC 2021 with Chapter 12 (energy systems) from IFC 2024. Political subdivisions with authority to enact a local fire code may adopt IFC appendices.', 'Ohio Adm. Code 1301:7-7-01 et seq.; R.C. 3737.82', 'https://codes.ohio.gov/ohio-administrative-code/rule-1301:7-7-01', '2025-11-20'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:ibc:2024')::uuid, 'OK', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IBC 2024. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Statewide minimum code for commercial construction. The OUBCC adopted none of the IBC 2024 appendices for the statewide minimum code, but local jurisdictions may adopt them. The IBC''s referenced-standards list is amended to cite the 2006 IECC (IECC-06). Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-2; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-building-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:irc:2024')::uuid, 'OK', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IRC 2024. Residential. Applies statewide. Local amendments are allowed. Statewide minimum code for one- and two-family dwellings and townhouses. The rule text adopts the second printing (October 2024). Chapter 11 (Energy Efficiency) is adopted with Oklahoma amendments, for example a Climate Zone 3 wood-frame wall U-factor of 0.067 instead of 0.060. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-6; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-residential-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:iebc:2024')::uuid, 'OK', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IEBC 2024. Applies statewide. Local amendments are allowed. Statewide minimum code for existing buildings. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-8; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-existing-building-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:ifc:2024')::uuid, 'OK', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IFC 2024. Applies statewide. Local amendments are allowed. Statewide minimum fire code adopted by the OUBCC. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-4; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-fire-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:ifgc:2024')::uuid, 'OK', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IFGC 2024. Applies statewide. Local amendments are allowed. Statewide minimum fuel gas code. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-12; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-fuel-gas-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:imc:2024')::uuid, 'OK', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IMC 2024. Applies statewide. Local amendments are allowed. Statewide minimum mechanical code. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-14; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-mechanical-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:ipc:2024')::uuid, 'OK', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'Oklahoma adopted IPC 2024. Applies statewide. Local amendments are allowed. Statewide minimum plumbing code. Replaced the 2018 edition, which was in effect until 2026-09-14.', 'OAC 748:20-16; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/international-plumbing-code-adoptions.html', '2026-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OK:nec:2023')::uuid, 'OK', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Oklahoma adopted NEC 2023. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Statewide minimum code for commercial electrical construction. Residential electrical work falls under the electrical chapters of the adopted IRC. A technical committee is reviewing the 2026 NEC.', 'OAC 748:20-10; 59 O.S. 1000.23', 'https://oklahoma.gov/oubcc/codes-and-rules/national-electrical-code-adoptions.html', '2024-09-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:ibc:2024')::uuid, 'OR', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, '2025 Oregon Structural Specialty Code (OSSC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Includes the 2024 IFC new-construction provisions and the 2024 IEBC. Chapter 1 took effect October 1, 2025. Construction provisions had a phase-in and became mandatory April 1, 2026.', 'OAR 918-460-0010; ORS 455.040', 'https://www.oregon.gov/bcd/codes-stand/Pages/ossc-adoption.aspx', '2025-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:iebc:2024')::uuid, 'OR', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, '2025 Oregon Structural Specialty Code (incorporates the 2024 IEBC). Applies statewide. Local governments may not amend it. Adopted as part of the OSSC, not as a separate code.', 'OAR 918-460-0010', 'https://www.oregon.gov/bcd/codes-stand/Pages/ossc-adoption.aspx', '2025-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:irc:2024')::uuid, 'OR', md5('academykb:source:irc-2024')::uuid, 'adopts', null, '2026 Oregon Residential Specialty Code (ORSC). Residential. Applies statewide. Local governments may not amend it. Chapter 1 is effective and mandatory October 1, 2026. Chapters 2-44 are in a phase-in period and become mandatory April 1, 2027; until then the 2023 ORSC (2021 IRC based) may also be used. Residential energy provisions are in ORSC Chapter 11. Low-rise plumbing provisions are in the OPSC.', 'OAR 918-480-0005 (BCD 14-2026)', 'https://www.oregon.gov/bcd/codes-stand/Pages/orsc-adoption.aspx', '2026-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:imc:2024')::uuid, 'OR', md5('academykb:source:imc-2024')::uuid, 'adopts', null, '2025 Oregon Mechanical Specialty Code (OMSC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Includes the 2024 IFGC. Phase-in ended March 31, 2026. Dwellings under the ORSC use the ORSC mechanical chapters.', 'OAR 918-440-0010', 'https://www.oregon.gov/bcd/codes-stand/Pages/omsc-adoption.aspx', '2025-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:ifgc:2024')::uuid, 'OR', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, '2025 Oregon Mechanical Specialty Code (incorporates the 2024 IFGC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Adopted as part of the OMSC.', 'OAR 918-440-0010', 'https://www.oregon.gov/bcd/codes-stand/Pages/omsc-adoption.aspx', '2025-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:upc:2024')::uuid, 'OR', md5('academykb:source:upc-2024')::uuid, 'adopts', null, '2026 Oregon Plumbing Specialty Code (OPSC). Applies statewide. Local governments may not amend it. UPC Chapter 12 is not adopted. Local jurisdictions may adopt Appendices L and N.', 'OAR 918-750-0110 (BCD 13-2026)', 'https://www.oregon.gov/bcd/codes-stand/Pages/opsc-adoption.aspx', '2026-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:ifc:2024')::uuid, 'OR', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, '2025 Oregon Fire Code. Applies statewide. Adopted by the Department of the State Fire Marshal. The plan-review phase-in ended March 31, 2026.', 'OAR 837-040-0010; ORS 476.030', 'https://secure.sos.state.or.us/oard/displayDivisionRules.action?selectedDivision=3805', '2025-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:ashrae_90_1:2022')::uuid, 'OR', md5('academykb:source:ashrae_90_1-2022')::uuid, 'adopts', null, '2025 Oregon Energy Efficiency Specialty Code (OEESC). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Commercial energy code. A 6-month phase-in made it mandatory July 1, 2025 (BCD adopted-codes page). Residential energy is in ORSC Chapter 11. The Oregon Reach Code is optional.', 'OAR 918-460-0500', 'https://www.oregon.gov/bcd/codes-stand/Pages/energy-efficiency.aspx', '2025-01-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:OR:nec:2026')::uuid, 'OR', md5('academykb:source:nec-2026')::uuid, 'adopts', null, '2026 Oregon Electrical Specialty Code (OESC). Applies statewide. Local governments may not amend it. Also adopts the NESC (IEEE C2-2023).', 'OAR 918-305-0100; OAR 918-305-0105 (Table 1-E)', 'https://www.oregon.gov/bcd/codes-stand/Pages/oesc-adoption.aspx', '2026-10-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:ibc:2021')::uuid, 'PA', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IBC 2021, as amended). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:irc:2021')::uuid, 'PA', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IRC 2021, as amended). Residential. Applies statewide. Local amendments are allowed. PA keeps 8 1/4-inch max riser and non-interconnected smoke alarms for alterations, among other amendments. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:ipc:2021')::uuid, 'PA', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IPC 2021). Applies statewide. Local amendments are allowed. Municipalities in counties of the second class (Allegheny County) do not enforce the IPC; local Health Administration Law plumbing codes apply there. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:imc:2021')::uuid, 'PA', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IMC 2021). Applies statewide. Local amendments are allowed. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:ifgc:2021')::uuid, 'PA', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IFGC 2021). Applies statewide. Local amendments are allowed. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:ifc:2021')::uuid, 'PA', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IFC 2021, limited). Applies statewide. Local amendments are allowed. IFC adopted only to the extent referenced by the other adopted ICC codes; PA has no general statewide fire prevention code adoption under the UCC. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:iecc:2021')::uuid, 'PA', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IECC 2021, as amended). Applies statewide. Local amendments are allowed. Commercial and residential provisions carry PA modifications; § 403.21 also references PA prescriptive residential energy provisions as an alternative path. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:PA:iebc:2021')::uuid, 'PA', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Pennsylvania Uniform Construction Code (IEBC 2021, as amended). Applies statewide. Local amendments are allowed. Accessibility provisions of the IEBC 2021 are excluded. Current § 403.21 text: Source note ''amended November 7, 2025, effective January 1, 2026, 55 Pa.B. 7701''.', '34 Pa. Code § 403.21; Pennsylvania Construction Code Act (35 P.S. § 7210.101 et seq.)', 'https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/034/chapter403/s403.21.html', '2026-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:ibc:2021')::uuid, 'RI', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Rhode Island Building Code (510-RICR-00-00-1, RISBC-1). Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it.', '510-RICR-00-00-1; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-1', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:irc:2021')::uuid, 'RI', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Rhode Island One & Two-Family Dwelling Code (510-RICR-00-00-2, RISBC-2). Residential. Applies statewide. Local governments may not amend it.', '510-RICR-00-00-2; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-2', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:ipc:2021')::uuid, 'RI', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'Rhode Island Plumbing Code (510-RICR-00-00-3, RISBC-3). Applies statewide. Local governments may not amend it.', '510-RICR-00-00-3; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-3', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:imc:2021')::uuid, 'RI', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Rhode Island Mechanical Code (510-RICR-00-00-4, RISBC-4). Applies statewide. Local governments may not amend it.', '510-RICR-00-00-4; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-4', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:nec:2023')::uuid, 'RI', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Rhode Island Electrical Code (510-RICR-00-00-5, RISBC-5). Applies statewide. Local governments may not amend it. State law requires electrical work statewide to follow the latest NEC edition (R.I. Gen. Laws 23-27.3-100.1.5).', '510-RICR-00-00-5; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-5', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:iebc:2021')::uuid, 'RI', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Rhode Island Existing Building Code (510-RICR-00-00-7). Applies statewide. Local governments may not amend it. New Part 7 replacing former IBC Chapter 34 RI amendments.', '510-RICR-00-00-7; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-7', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:iecc:2024')::uuid, 'RI', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'Rhode Island Energy Conservation Code (510-RICR-00-00-8, RISBC-8). Applies statewide. Local governments may not amend it. Covers both commercial and residential parts of the 2024 IECC; statute (23-27.3-100.1.5.4) barred adoption of 2021 IECC and required 2024 IECC.', '510-RICR-00-00-8; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-8', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:ifgc:2021')::uuid, 'RI', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Rhode Island Fuel Gas Code (510-RICR-00-00-19, RISBC-19). Applies statewide. Local governments may not amend it.', '510-RICR-00-00-19; R.I. Gen. Laws 23-27.3-100.1.5 and 23-27.3-109.1', 'https://rules.sos.ri.gov/regulations/Part/510-00-00-19', '2025-12-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:RI:nfpa1:2021')::uuid, 'RI', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, 'Rhode Island Fire Code (450-RICR-00-00-7, RIFC). Applies statewide. Adopted by the Fire Safety Code Board of Appeal and Review; companion RI Life Safety Code (NFPA 101) is 450-RICR-00-00-8.', '450-RICR-00-00-7; R.I. Gen. Laws 23-28.3-3', 'https://rules.sos.ri.gov/regulations/Part/450-00-00-7', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:ibc:2021')::uuid, 'SC', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, '2021 South Carolina Building Code. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:irc:2021')::uuid, 'SC', md5('academykb:source:irc-2021')::uuid, 'adopts', null, '2021 South Carolina Residential Code. Residential. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:ifc:2021')::uuid, 'SC', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, '2021 South Carolina Fire Code. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:ipc:2021')::uuid, 'SC', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, '2021 South Carolina Plumbing Code. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:imc:2021')::uuid, 'SC', md5('academykb:source:imc-2021')::uuid, 'adopts', null, '2021 South Carolina Mechanical Code. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:ifgc:2021')::uuid, 'SC', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, '2021 South Carolina Fuel Gas Code. Applies statewide. Local amendments are allowed. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:nec:2020')::uuid, 'SC', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'National Electrical Code (NFPA 70) with SC modifications. Applies statewide. Local amendments are allowed. 2023 NEC with SC modifications takes effect 2027-01-01. Local modifications are valid only if approved by the SC Building Codes Council; the 2024 edition takes effect 2027-01-01.', 'S.C. Code Ann. § 6-9-50', 'https://llr.sc.gov/bcc/BCAdoption.aspx', '2023-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:iecc:2009')::uuid, 'SC', md5('academykb:source:iecc-2009')::uuid, 'adopts', null, 'South Carolina Building Energy Efficiency Standard (2009 IECC by statute). Applies statewide. Set by statute, not by the Building Codes Council; the 2024 code update does not change the energy code.', 'S.C. Code Ann. § 6-10-10 et seq. (Building Energy Efficiency Standard Act)', 'https://llr.sc.gov/bcc/PDFfiles/2024%20Code%20Adoption%20Notice.pdf', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:SC:iebc:international-existing-building-code-permissive-co')::uuid, 'SC', md5('academykb:source:st:SC:iebc:international-existing-building-code-permissive-co')::uuid, 'adopts', null, 'International Existing Building Code (permissive code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Permissive code: applies only where a municipality or county adopts it by ordinance.', 'S.C. Code Ann. § 6-9-60', 'https://llr.sc.gov/bcc/PDFfiles/Building%20Codes%20in%20Effect%20for%20South%20Carolina%20Final.pdf', null, null, true, '{}'::text[], 'pending_review', null, 'Statute refers to the ''latest edition''; the specific IEBC edition each locality has adopted is not stated statewide.'),
  (md5('academykb:adoption:st:SD:ibc:2024')::uuid, 'SD', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'International Building Code (SDCL 11-10-5 / 11-10-6). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Applies to buildings other than one- and two-family dwellings/townhouses (SDCL 11-10-12 ''residential structure''), farmsteads, and HUD manufactured homes. Local codes must comply with the 2024 IBC but may amend it; where no local ordinance exists the 2024 IBC is the design standard for buildings commenced after July 1, 2026. Local ordinances may not require sprinklers in single-family dwellings.', 'SDCL 11-10-5; SDCL 11-10-6', 'https://sdlegislature.gov/Statutes/11-10-6', '2026-07-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:SD:irc:2024')::uuid, 'SD', md5('academykb:source:irc-2024')::uuid, 'adopts', null, 'International Residential Code (SDCL 11-10-12, local option). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Local option for municipalities only. If adopted, a municipality may amend it but may not require residential sprinklers or be more stringent than the 2024 IRC. Covers detached one- and two-family dwellings and townhouses up to three stories.', 'SDCL 11-10-12', 'https://sdlegislature.gov/Statutes/11-10-12', null, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:SD:iecc:2009')::uuid, 'SD', md5('academykb:source:iecc-2009')::uuid, 'adopts', null, 'International Energy Conservation Code (voluntary standard, new residential). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Voluntary standard only; not mandatory. Builders must give energy-efficiency disclosures to buyers (SDCL 11-10-8 to 11-10-10).', 'SDCL 11-10-7', 'https://sdlegislature.gov/Statutes/11-10-7', null, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:SD:nec:2023')::uuid, 'SD', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'National Electrical Code as adopted by the South Dakota Electrical Commission. Applies statewide. 2023 NEC including TIAs 23-1 through 23-15, with listed state exceptions. Inspections by the state Electrical Commission or approved local inspection systems.', 'ARSD 20:44:22:01; ARSD 20:44:14:01(11)', 'https://sdlegislature.gov/Rules/Administrative/20:44:14:01', '2024-11-12'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:SD:upc:2024')::uuid, 'SD', md5('academykb:source:upc-2024')::uuid, 'adopts', null, 'Uniform Plumbing Code as adopted by the South Dakota Plumbing Commission. Applies statewide. 2024 UPC with Appendices A, B, C, D, E, I, K, L, M, N, O, Q and R and numerous state exceptions (e.g., 72-inch water service cover, no water piping in exterior walls).', 'ARSD 20:54:02:01', 'https://sdlegislature.gov/Rules/Administrative/20:54:02:01', null, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:SD:ifc:2015')::uuid, 'SD', md5('academykb:source:ifc-2015')::uuid, 'adopts', null, 'South Dakota fire safety standards (IFC/IBC/IMC 2015, Dept. of Public Safety). Commercial and other non-residential buildings. Applies statewide. State fire safety rules of the Department of Public Safety (State Fire Marshal). Precise occupancy scope of state enforcement not confirmed; ARSD 61:15:01:16 lets local officials approve alternatives for certain chapters.', 'ARSD 61:15:01:01; SDCL 34-29B-2', 'https://sdlegislature.gov/Rules/Administrative/61:15:01:01', '2016-10-17'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:TN:irc:2018')::uuid, 'TN', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'Tennessee residential code (2018 IRC with amendments), Chapter 0780-02-23. Residential. Applies statewide. One- and two-family dwellings and townhouses. Not in force in exempt jurisdictions or in counties/municipalities that opted out under T.C.A. 68-120-101(b). R313 sprinklers not mandatory; IRC electrical chapters deleted in favor of 0780-02-01.', 'Tenn. Comp. R. & Regs. 0780-02-23-.02', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-23.20260923.pdf', '2020-07-16'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:iecc:2018')::uuid, 'TN', md5('academykb:source:iecc-2018')::uuid, 'adopts', null, 'IECC 2018 with Tennessee amendments (residential). Residential. Applies statewide. Residential energy code for one- and two-family dwellings and townhouses; same opt-out rules as the residential code.', 'Tenn. Comp. R. & Regs. 0780-02-23-.02', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-23.20260923.pdf', '2020-07-16'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:ibc:2021')::uuid, 'TN', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'International Building Code, 2021 edition (Tennessee amendments). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:ifgc:2021')::uuid, 'TN', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'International Fuel Gas Code, 2021 edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:imc:2021')::uuid, 'TN', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'International Mechanical Code, 2021 edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:ipc:2021')::uuid, 'TN', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'International Plumbing Code, 2021 edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:ifc:2021')::uuid, 'TN', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'International Fire Code, 2021 edition (Tennessee amendments). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:iecc:2021')::uuid, 'TN', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'International Energy Conservation Code, 2021 edition (commercial, Tennessee amendments). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025). The 2006 IECC applies to F-1, F-2, S-1 and S-2 occupancies; the 2015 edition applies to DHS-licensed daycares not in a dwelling unit.', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:iebc:2021')::uuid, 'TN', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'International Existing Building Code, 2021 edition (Tennessee amendments). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State minimum code for buildings under State Fire Marshal jurisdiction; ''exempt jurisdictions'' approved by the SFMO adopt and enforce their own codes (edition within 7 years of the latest) and may not adopt less stringent standards without SFMO approval. Effective April 17, 2025 (plans could be submitted under prior codes until Aug. 15, 2025).', 'Tenn. Comp. R. & Regs. 0780-02-02-.01', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-02.20250417.pdf', '2025-04-17'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TN:nec:2017')::uuid, 'TN', md5('academykb:source:nec-2017')::uuid, 'adopts', null, 'National Electrical Code, 2017 edition (Tennessee amendments). Applies statewide. Statewide electrical installation standard; 110.24 available fault current optional and some AFCI locations optional. Local electrical inspection programs may operate under state rules.', 'Tenn. Comp. R. & Regs. 0780-02-01-.02', 'https://publications.tnsosfiles.com/rules/0780/0780-02/0780-02-01.20250714.pdf', '2018-10-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:irc:2012')::uuid, 'TX', md5('academykb:source:irc-2012')::uuid, 'adopts', null, 'Municipal residential building code (International Residential Code as it existed on May 1, 2012). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Applies inside municipalities only. Cities may adopt later ICC amendments and local amendments, by ordinance after a public hearing. The IRC electrical provisions do not apply (LGC 214.213).', 'Tex. Local Gov''t Code § 214.212', 'https://tcss.legis.texas.gov/resources/LG/htm/LG.214.htm', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:ibc:2012')::uuid, 'TX', md5('academykb:source:ibc-2012')::uuid, 'adopts', null, 'Municipal commercial building code (International Building Code as it existed on May 1, 2012). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Applies to commercial buildings inside municipalities. A city with a more stringent code may keep it and adopt future editions.', 'Tex. Local Gov''t Code § 214.216', 'https://tcss.legis.texas.gov/resources/LG/htm/LG.214.htm', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:iecc:2015')::uuid, 'TX', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, 'Texas Building Energy Efficiency Performance Standards – single-family (2015 IRC Chapter 11). Residential. Applies statewide. The model code is the energy chapter (Ch. 11) of the 2015 IRC, not the IECC itself. It covers one- and two-family homes of three stories or fewer. Outside city limits, HSC 388.004 lets compliance be shown by certification, a private inspection or a builder form. The ERI compliance path is set by statute.', 'Tex. Health & Safety Code § 388.003(a)', 'https://comptroller.texas.gov/programs/seco/code/single-family.php', '2016-09-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:iecc:2015')::uuid, 'TX', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, 'Texas energy code for commercial, industrial and multifamily construction (2015 IECC). Commercial and other non-residential buildings. Applies statewide. Covers commercial and industrial buildings and residential buildings taller than three stories. SECO has elected to keep the 2015 IECC rather than adopt a newer edition.', 'Tex. Health & Safety Code § 388.003(b); 34 TAC § 19.53', 'https://comptroller.texas.gov/programs/seco/code/commercial.php', '2016-11-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:nec:2026')::uuid, 'TX', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'Texas state electrical code (National Electrical Code). Applies statewide. Local amendments are allowed. Adopted with a limited exception for GFCI requirements on certain outdoor outlets. Under LGC 214.214, municipalities may adopt local NEC amendments, but they may not regulate residential energy backup systems.', '16 TAC § 73.100; Tex. Occ. Code § 1305.101(a)(2)', 'https://www.tdlr.texas.gov/news/rulemaking/2026/09/01/commission-adopts-rules-12/', '2026-09-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:upc:2021')::uuid, 'TX', md5('academykb:source:upc-2021')::uuid, 'adopts', null, 'TSBPE-adopted plumbing codes (Uniform Plumbing Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. The board adopts both the UPC and the IPC. Plumbing must follow the code adopted by the local political subdivision. Where none is adopted (for example unincorporated areas), licensed plumbers must use a board-adopted code (UPC or IPC). Locals may amend as long as the amendments do not substantially vary from state rules.', '22 TAC § 367.2; Tex. Occ. Code § 1301.255', 'https://www.sos.state.tx.us/texreg/archive/November132026/Adopted%20Rules/22.EXAMINING%20BOARDS.html', '2026-11-19'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:TX:ipc:2021')::uuid, 'TX', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'TSBPE-adopted plumbing codes (International Plumbing Code, incl. referenced 2021 IFGC and IRC). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local amendments are allowed. Alternative to the UPC. It brings in the 2021 IFGC and the 2021 IRC as referenced codes for plumbing purposes.', '22 TAC § 367.2; Tex. Occ. Code § 1301.255', 'https://www.sos.state.tx.us/texreg/archive/November132026/Adopted%20Rules/22.EXAMINING%20BOARDS.html', '2026-11-19'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:ibc:2024')::uuid, 'UT', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Building Code. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026), which takes effect July 1, 2026. Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(a); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:irc:2021')::uuid, 'UT', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Utah State Construction Code - International Residential Code. Residential. Applies statewide. Local governments may not amend it. The IRC edition was not changed by H.B. 65 (2026); Utah amended its IRC amendments only. IRC Appendix AQ (2021) is also adopted. No effective date captured for the 2021 IRC. Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(b); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', null, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:iebc:2024')::uuid, 'UT', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Existing Building Code. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026). Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(i); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:ipc:2024')::uuid, 'UT', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Plumbing Code. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026). Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(d); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:imc:2024')::uuid, 'UT', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Mechanical Code. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026). Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(e); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:ifgc:2024')::uuid, 'UT', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Fuel Gas Code. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026). The State Fire Code also incorporates NFPA 54 (2024). Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(f); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:iecc:2024')::uuid, 'UT', md5('academykb:source:iecc-2024')::uuid, 'adopts', null, 'Utah State Construction Code - International Energy Conservation Code. Applies statewide. Local governments may not amend it. Changed from 2021 to 2024 by H.B. 65 (2026). One- and two-family dwellings built under the IRC follow IRC Chapter 11 (2021 IRC with Utah amendments), so the residential energy requirements differ from the 2024 IECC; this was not separately verified. Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(h); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', '2026-07-01'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:nec:2023')::uuid, 'UT', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Utah State Construction Code - National Electrical Code. Applies statewide. Local governments may not amend it. The NEC edition was not changed by H.B. 65 (2026). No effective date captured for the 2023 NEC. Political subdivisions may not adopt or enforce requirements more restrictive than the State Construction Code (15A-1-204(8)). Local amendments exist only as enacted by the Legislature in Title 15A, Chapter 4.', 'Utah Code 15A-2-103(1)(g); statewide amendments Title 15A, Chapter 3', 'https://le.utah.gov/xcode/Title15A/Chapter2/C15A-2-S103_2026050620260701.html', null, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:UT:ifc:2024')::uuid, 'UT', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'Utah State Fire Code - International Fire Code. Applies statewide. Appendices excluded. Also incorporates NFPA 1 Ch. 38, NFPA 54 and NFPA 58 (2024 editions). The effective date is that of the current section text (amended by Ch. 34, 2026 General Session); not confirmed whether the IFC edition itself changed on that date.', 'Utah Code 15A-5-103(1); statewide amendments Title 15A, Chapter 5, Part 2', 'https://le.utah.gov/xcode/Title15A/Chapter5/C15A-5-S103_2026050620260701.html', '2026-07-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:ibc:2021')::uuid, 'VA', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Virginia Construction Code (VCC), USBC Part I. Commercial and other non-residential buildings. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:irc:2021')::uuid, 'VA', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Virginia Residential Code (IRC as amended within the VCC). Residential. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:ipc:2021')::uuid, 'VA', md5('academykb:source:ipc-2021')::uuid, 'adopts', null, 'International Plumbing Code as amended in the VCC. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:imc:2021')::uuid, 'VA', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'International Mechanical Code as amended in the VCC. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:ifgc:2021')::uuid, 'VA', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'International Fuel Gas Code as amended in the VCC. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:iecc:2021')::uuid, 'VA', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'International Energy Conservation Code as amended in the VCC. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:nec:2020')::uuid, 'VA', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'NFPA 70 (National Electrical Code) as referenced in the VCC. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63 (Virginia Construction Code, Part I of the USBC); Code of Va. § 36-98', 'https://law.lis.virginia.gov/admincode/title13/agency5/chapter63/section10/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:iebc:2021')::uuid, 'VA', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Virginia Existing Building Code (VEBC), USBC Part II. Applies statewide. Local governments may not amend it. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-63-400 et seq. (Virginia Existing Building Code, Part II of the USBC)', 'https://law.lis.virginia.gov/admincodefull/title13/agency5/chapter63/partII/', '2024-01-18'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VA:ifc:2021')::uuid, 'VA', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'Virginia Statewide Fire Prevention Code (SFPC). Applies statewide. Local governments may choose whether to enforce the SFPC (13VAC5-52-40, 104.1: ''Any local government may enforce the SFPC following official action by such body''); the State Fire Marshal enforces where locals do not and in state-owned buildings. Effective date per DHCD: The effective date of the 2021 Uniform Statewide Building Code, 2021 Statewide Fire Prevention Code, 2021 Industrialized Building Safety Regulations and the 2021 Amusement Device Regulations is Jan. 18, 2024.', '13VAC5-52 (Statewide Fire Prevention Code); Code of Va. § 27-97', 'https://law.lis.virginia.gov/admincodefull/title13/agency5/chapter52/', '2024-01-18'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:ibc:2021')::uuid, 'VT', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Vermont Fire & Building Safety Code – 2025 (IBC 2021 as amended). Commercial and other non-residential buildings. Applies statewide. Applies only to ''public buildings'' as defined in 20 V.S.A. § 2730 (commercial, multifamily, rental, condo, etc.); owner-occupied single-family homes are excluded. Enforced by the Division of Fire Safety or municipalities with an inspection agreement.', 'Vermont Fire & Building Safety Code - 2025 (adopted under 20 V.S.A. ch. 173)', 'https://firesafety.vermont.gov/buildingcode/codes', '2025-11-04'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:iebc:2021')::uuid, 'VT', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Vermont Fire & Building Safety Code – 2025 (IEBC 2021 as amended). Commercial and other non-residential buildings. Applies statewide. Applies only to ''public buildings'' as defined in 20 V.S.A. § 2730 (commercial, multifamily, rental, condo, etc.); owner-occupied single-family homes are excluded. Enforced by the Division of Fire Safety or municipalities with an inspection agreement.', 'Vermont Fire & Building Safety Code - 2025 (adopted under 20 V.S.A. ch. 173)', 'https://firesafety.vermont.gov/buildingcode/codes', '2025-11-04'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:nfpa1:2021')::uuid, 'VT', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, 'Vermont Fire & Building Safety Code – 2025 (NFPA 1 2021 as amended). Commercial and other non-residential buildings. Applies statewide. Applies only to ''public buildings'' as defined in 20 V.S.A. § 2730 (commercial, multifamily, rental, condo, etc.); owner-occupied single-family homes are excluded. Enforced by the Division of Fire Safety or municipalities with an inspection agreement. NFPA 101 (2021) is also adopted and applies to all public buildings.', 'Vermont Fire & Building Safety Code - 2025 (adopted under 20 V.S.A. ch. 173)', 'https://firesafety.vermont.gov/buildingcode/codes', '2025-11-04'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:nec:2023')::uuid, 'VT', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Vermont Electrical Safety Rules (2025). Applies statewide. Rules do not apply to a single-family owner-occupied dwelling (single-family rentals and rental ADUs are covered), owner-occupied farm buildings, and utility installations. Rule section 10(b): ''These rules shall take effect November 5th, 2025 and shall be known as The Vermont Electrical Safety Rules.''', 'Vermont Electrical Safety Rules, adopted by the Electricians'' Licensing Board (26 V.S.A. ch. 15)', 'https://firesafety.vermont.gov/buildingcode/codes', '2025-11-05'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:ipc:2024')::uuid, 'VT', md5('academykb:source:ipc-2024')::uuid, 'adopts', null, 'Vermont Plumbing Rules (2025). Applies statewide. Applies to all public buildings and to all other buildings (including owner-occupied single-family homes) connected to a public water or sewerage system.', 'Vermont Plumbing Rules, 26 V.S.A. § 2173 (Plumbers'' Examining Board)', 'https://firesafety.vermont.gov/buildingcode/codes', '2025-11-04'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:state_energy:vermont-residential-building-energy-standards-rbes')::uuid, 'VT', md5('academykb:source:st:VT:state_energy:vermont-residential-building-energy-standards-rbes')::uuid, 'adopts', null, 'Vermont Residential Building Energy Standards (RBES), 2020 or 2024. Residential. Applies statewide. Applies statewide to all new residential construction, additions, alterations, renovations and repairs; builder certifies compliance (RBES certificate). The revised rule lets builders comply with either the 2020 or 2024 RBES. RBES Stretch Code applies to Act 250 projects.', '30 V.S.A. § 51', 'https://publicservice.vermont.gov/efficiency/building-energy-standards/residential-building-energy-standards', '2026-07-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:VT:state_energy:vermont-commercial-building-energy-standards-cbes-')::uuid, 'VT', md5('academykb:source:st:VT:state_energy:vermont-commercial-building-energy-standards-cbes-')::uuid, 'adopts', null, 'Vermont Commercial Building Energy Standards (CBES), 2020 or 2024. Commercial and other non-residential buildings. Applies statewide. Applies statewide to new commercial construction, additions, alterations, renovations and repairs; either 2020 or 2024 CBES may be used. ASHRAE 90.1-2019 is an alternative compliance path per the Department of Public Service.', '30 V.S.A. § 53', 'https://publicservice.vermont.gov/efficiency/building-energy-standards/commercial-building-energy-standards', '2026-07-14'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:ibc:2021')::uuid, 'WA', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Washington State Building Code - International Building Code (as amended). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. Local amendments allowed under RCW 19.27.040 but may not diminish minimum performance standards. 2024 edition adoption is in progress (CR-103 ''date tbd'').', 'RCW 19.27.031; WAC 51-50-003 (chapter 51-50 WAC)', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-50', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:iebc:2021')::uuid, 'WA', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, '2021 International Existing Building Code (as amended in WAC 51-50-480000). Applies statewide. Local amendments are allowed. Adopted as part of the IBC adoption (IBC Section 101.4.7).', 'WAC 51-50-007; WAC 51-50-480000', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-50', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:irc:2021')::uuid, 'WA', md5('academykb:source:irc-2021')::uuid, 'adopts', null, 'Washington State Residential Code - International Residential Code (as amended). Residential. Applies statewide. Local amendments are allowed. IRC chapters 11 and 25-43 not adopted: energy is chapter 51-11R WAC, plumbing chapter 51-56 WAC, electrical chapter 296-46B WAC. Effective date taken from the SBCC statement that all 2021 codes took effect March 15, 2024.', 'RCW 19.27.031; WAC 51-51-003 (chapter 51-51 WAC)', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-51', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:imc:2021')::uuid, 'WA', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Washington State Mechanical Code - International Mechanical Code (as amended). Applies statewide. Local amendments are allowed. LP-gas installations use NFPA 58 and NFPA 54 per RCW 19.27.031(1)(b).', 'RCW 19.27.031; WAC 51-52-003 (chapter 51-52 WAC)', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-52', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:ifgc:international-fuel-gas-code-adopted-within-chapter')::uuid, 'WA', md5('academykb:source:st:WA:ifgc:international-fuel-gas-code-adopted-within-chapter')::uuid, 'adopts', null, 'International Fuel Gas Code (adopted within chapter 51-52 WAC). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. WAC 51-52 amends IFGC sections, and the IMC scope says fuel gas systems are regulated by the IFGC. Detached one- and two-family dwellings and townhouses follow the IRC.', 'WAC 51-52-0101; WAC 51-52-21000 through 51-52-22000', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-52', null, null, true, '{}'::text[], 'pending_review', null, 'No WAC section found that states the IFGC edition year outright (WAC 51-52-21000 is a heading only). Presumably 2021 with the IMC, but this is not confirmed.'),
  (md5('academykb:adoption:st:WA:ifc:2021')::uuid, 'WA', md5('academykb:source:ifc-2021')::uuid, 'adopts', null, 'Washington State Fire Code - International Fire Code (as amended). Applies statewide. Local amendments are allowed.', 'RCW 19.27.031; WAC 51-54A-003 (chapter 51-54A WAC)', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-54A', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:upc:2021')::uuid, 'WA', md5('academykb:source:upc-2021')::uuid, 'adopts', null, 'Washington State Plumbing Code - Uniform Plumbing Code (as amended). Applies statewide. Local amendments are allowed. UPC chapters 12 and 14 not adopted, nor its fuel-fired appliance venting/combustion air and building sewer provisions. Effective date taken from the SBCC statement that all 2021 codes took effect March 15, 2024.', 'RCW 19.27.031; WAC 51-56-003 (chapter 51-56 WAC)', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-56', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:state_energy:2021')::uuid, 'WA', md5('academykb:source:st:WA:state_energy:washington-state-energy-code-commercial-provisions')::uuid, 'adopts', null, 'Washington State Energy Code - Commercial Provisions (WSEC-C). Commercial and other non-residential buildings. Applies statewide. A state-written energy code based on the IECC, with Washington-specific requirements. A 2024 WSEC-C was proposed (CR-102 07/01/2026); its adoption date is TBD.', 'WAC 51-11C-10100 (chapter 51-11C WAC); chapter 19.27A RCW', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-11C', '2024-03-15'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:state_energy:2021')::uuid, 'WA', md5('academykb:source:st:WA:state_energy:washington-state-energy-code-residential-provision')::uuid, 'adopts', null, 'Washington State Energy Code - Residential Provisions (WSEC-R). Residential. Applies statewide. Local governments may not amend it. This code is the maximum and minimum residential energy code, so locals may not amend it up or down. An emergency rule amending R101.2 for 2026 wildfire rebuilding was filed November 4, 2026.', 'WAC 51-11R-10100 (chapter 51-11R WAC); chapter 19.27A RCW', 'https://app.leg.wa.gov/WAC/default.aspx?cite=51-11R', '2024-03-15'::date, null, false, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WA:nec:2023')::uuid, 'WA', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Washington Electrical Code - Safety Standards for Electrical Installations (NEC as amended). Applies statewide. Administered by the Department of Labor & Industries. The 2026 NEC replaces the 2023 NEC effective December 31, 2026. No official effective date for the 2023 NEC adoption was captured.', 'chapter 19.28 RCW; WAC 296-46B-010', 'https://app.leg.wa.gov/WAC/default.aspx?cite=296-46B-010', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:state_residential:wisconsin-uniform-dwelling-code-udc')::uuid, 'WI', md5('academykb:source:st:WI:state_residential:wisconsin-uniform-dwelling-code-udc')::uuid, 'adopts', null, 'Wisconsin Uniform Dwelling Code (UDC). Residential. Applies statewide. State-written code for new one- and two-family dwellings, including manufactured home installations. A delegated municipality enforces it, or DSPS does.', 'Wis. Admin. Code chs. SPS 320-325', 'https://dsps.wi.gov/a-z-programs-list/udc/', null, null, true, '{}'::text[], 'pending_review', null, 'The UDC is a state-written code and clearly in force, but I could not reach the rule text (docs.legis.wisconsin.gov returned 503 / connection reset) to confirm the citation, the current revision''s effective date or the local amendment rules.'),
  (md5('academykb:adoption:st:WI:iecc:2009')::uuid, 'WI', md5('academykb:source:iecc-2009')::uuid, 'adopts', null, 'Wisconsin Uniform Dwelling Code energy conservation provisions. Residential. Applies statewide. Energy chapter of the UDC for one- and two-family dwellings. Low-rise multifamily envelope compliance uses REScheck under the 2015 IECC, per the commercial program page. The SPS 322 citation is from my knowledge and not confirmed on an official page reached.', 'Wis. Admin. Code ch. SPS 322', 'https://dsps.wi.gov/a-z-programs-list/udc/', '2016-01-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:ibc:2021')::uuid, 'WI', md5('academykb:source:ibc-2021')::uuid, 'adopts', null, 'Wisconsin Commercial Building Code. Commercial and other non-residential buildings. Applies statewide. Commercial buildings and multifamily housing of 3 or more units. DSPS or a delegated municipality reviews the plans.', 'Wis. Admin. Code chs. SPS 361-366 (IBC amendments in SPS 362)', 'https://dsps.wi.gov/Pages/Programs/CommercialBuildings/Default.aspx', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:iecc:2021')::uuid, 'WI', md5('academykb:source:iecc-2021')::uuid, 'adopts', null, 'Wisconsin Commercial Building Code energy provisions (SPS 363). Commercial and other non-residential buildings. Applies statewide. Applies to commercial and high-rise (over 3 stories) multifamily buildings. ASHRAE 90.1-2019 is allowed through 2021 IECC C401.2.2.', 'Wis. Admin. Code ch. SPS 363', 'https://dsps.wi.gov/a-z-programs-list/electrical/', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:imc:2021')::uuid, 'WI', md5('academykb:source:imc-2021')::uuid, 'adopts', null, 'Wisconsin Commercial Building Code HVAC provisions (SPS 364). Commercial and other non-residential buildings. Applies statewide.', 'Wis. Admin. Code ch. SPS 364', 'https://dsps.wi.gov/Pages/Programs/CommercialBuildings/Default.aspx', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:ifgc:2021')::uuid, 'WI', md5('academykb:source:ifgc-2021')::uuid, 'adopts', null, 'Wisconsin Commercial Building Code fuel gas provisions (SPS 365). Commercial and other non-residential buildings. Applies statewide. Wisconsin amendment SPS 365.0501(4) requires plastic venting materials for fuel-fired equipment to meet UL 1738.', 'Wis. Admin. Code ch. SPS 365', 'https://dsps.wi.gov/Pages/Programs/CommercialBuildings/Default.aspx', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:iebc:2021')::uuid, 'WI', md5('academykb:source:iebc-2021')::uuid, 'adopts', null, 'Wisconsin Commercial Building Code existing building provisions (SPS 366). Commercial and other non-residential buildings. Applies statewide.', 'Wis. Admin. Code ch. SPS 366', 'https://dsps.wi.gov/Pages/Programs/CommercialBuildings/Default.aspx', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:nec:2023')::uuid, 'WI', md5('academykb:source:nec-2023')::uuid, 'adopts', null, 'Wisconsin Electrical Code. Applies statewide. Based on the 2023 NEC with Wisconsin changes and omissions; it replaced the 2017-NEC-based code. New requirements include whole-home surge protection, and permits and inspections for services on vacant land.', 'Wis. Admin. Code ch. SPS 316', 'https://dsps.wi.gov/a-z-boards-and-councils-list/sps-316-electrical/', '2026-09-01'::date, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null),
  (md5('academykb:adoption:st:WI:state_plumbing:wisconsin-plumbing-code')::uuid, 'WI', md5('academykb:source:st:WI:state_plumbing:wisconsin-plumbing-code')::uuid, 'adopts', null, 'Wisconsin Plumbing Code. Applies statewide. State-written plumbing code. DSPS or a delegated agent does plan review; the municipality issues permits and inspects.', 'Wis. Admin. Code chs. SPS 381-387', 'https://dsps.wi.gov/a-z-programs-list/plumbing/', null, null, true, '{}'::text[], 'pending_review', null, 'The DSPS release is dated ''June 1, 2025'' but sits under the 2026 news releases. The Sept 1, 2026 release puts the plumbing refresh alongside the 2026-09-01 electrical code. I could not reach the rule text to confirm the exact effective year, and the SPS 381-387 citation is not confirmed on an official page.'),
  (md5('academykb:adoption:st:WI:nfpa1:wisconsin-fire-prevention-code')::uuid, 'WI', md5('academykb:source:st:WI:nfpa1:wisconsin-fire-prevention-code')::uuid, 'adopts', null, 'Wisconsin Fire Prevention Code. Applies statewide.', 'Wis. Admin. Code ch. SPS 314', 'https://dsps.wi.gov/a-z-boards-and-councils-list/sps-314-fire-prevention/', null, null, true, '{}'::text[], 'pending_review', null, 'The NFPA 1 edition adopted in SPS 314 could not be confirmed. The rule text on docs.legis.wisconsin.gov was unreachable (503 / reset) and no DSPS page I reached names the edition.'),
  (md5('academykb:adoption:st:WV:ibc:2018')::uuid, 'WV', md5('academykb:source:ibc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Building Code). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend. References to the IFC are replaced with NFPA 101 Life Safety Code 2021. Commercial structures over 7,600 sq ft needing a certificate of occupancy must be designed by a WV-licensed architect or engineer.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:irc:2018')::uuid, 'WV', md5('academykb:source:irc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Residential Code). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend. State amendments include max riser 8-1/4 in., min tread 9 in., and floor fire-protection options in §87-4-5.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:iebc:2018')::uuid, 'WV', md5('academykb:source:iebc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Existing Building Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:ipc:2018')::uuid, 'WV', md5('academykb:source:ipc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Plumbing Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend. Where the IPC conflicts with Department of Health and Human Resources rules, the DHHR rules take precedence (§87-4-3.2).', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:imc:2018')::uuid, 'WV', md5('academykb:source:imc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Mechanical Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:ifgc:2018')::uuid, 'WV', md5('academykb:source:ifgc-2018')::uuid, 'adopts', null, 'West Virginia State Building Code (International Fuel Gas Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:iecc:2015')::uuid, 'WV', md5('academykb:source:iecc-2015')::uuid, 'adopts', null, 'West Virginia State Building Code (IECC, residential). Residential. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:ashrae_90_1:2013')::uuid, 'WV', md5('academykb:source:ashrae_90_1-2013')::uuid, 'adopts', null, 'West Virginia State Building Code (ASHRAE 90.1, commercial). Commercial and other non-residential buildings. Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:nec:2020')::uuid, 'WV', md5('academykb:source:nec-2020')::uuid, 'adopts', null, 'West Virginia State Building Code (National Electrical Code). Applies only where a local government adopts or enforces it, or to the buildings the state regulates. Local governments may not amend it. Applies only where a county or municipality adopts the State Building Code (87CSR4 §7); locals may complete discretionary provisions and adopt appendices but not otherwise amend. No separate statewide NEC adoption rule was confirmed; electrical inspectors are licensed by the State Fire Marshal (W. Va. Code ch. 29, art. 3C). Renovations in one- and two-family homes need AFCI only in bedrooms.', 'W. Va. Code R. § 87-4-4 (87CSR4); W. Va. Code § 15A-11-5', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-04', '2022-08-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WV:nfpa1:2021')::uuid, 'WV', md5('academykb:source:nfpa1-2021')::uuid, 'adopts', null, 'West Virginia State Fire Code (NFPA 1 and NFPA 101, 2021 editions). Commercial and other non-residential buildings. Applies statewide. Statewide fire code of the State Fire Commission; does not apply to dwellings for no more than two families, personal care homes for three or fewer patients, or agricultural buildings. Takes precedence over the State Building Code where they conflict.', 'W. Va. Code R. § 87-1-2 (87CSR1); W. Va. Code § 15A-11-3', 'https://apps.sos.wv.gov/adlaw/csr/rule.aspx?rule=87-01', '2026-07-01'::date, null, true, '{}'::text[], 'pending_review', null, 'Quoted evidence was not found on the official page when re-checked.'),
  (md5('academykb:adoption:st:WY:ibc:2024')::uuid, 'WY', md5('academykb:source:ibc-2024')::uuid, 'adopts', null, 'International Building Code, 2024 Edition (state minimum fire/life-safety standard). Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State-adopted minimum fire/building standards. The state fire marshal applies them through plan review of state and local government buildings, larger public buildings, assembly occupancies, child care centers and fuel dispensing facilities (W.S. 35-9-108(a)). Cities and counties with delegated authority must adopt equal or more stringent standards (W.S. 35-9-121).', 'Rules of the Council on Fire Prevention and Electrical Safety in Buildings, Ch. 1 §2(a); W.S. 35-9-106(a)', 'https://wsfm.wyo.gov/', null, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:WY:iebc:2024')::uuid, 'WY', md5('academykb:source:iebc-2024')::uuid, 'adopts', null, 'International Existing Building Code, 2024 Edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State-adopted minimum fire/building standards. The state fire marshal applies them through plan review of state and local government buildings, larger public buildings, assembly occupancies, child care centers and fuel dispensing facilities (W.S. 35-9-108(a)). Cities and counties with delegated authority must adopt equal or more stringent standards (W.S. 35-9-121).', 'Rules of the Council on Fire Prevention and Electrical Safety in Buildings, Ch. 1 §2(a); W.S. 35-9-106(a)', 'https://wsfm.wyo.gov/', null, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:WY:ifc:2024')::uuid, 'WY', md5('academykb:source:ifc-2024')::uuid, 'adopts', null, 'International Fire Code, 2024 Edition. Applies statewide. Local amendments are allowed. State-adopted minimum fire/building standards. The state fire marshal applies them through plan review of state and local government buildings, larger public buildings, assembly occupancies, child care centers and fuel dispensing facilities (W.S. 35-9-108(a)). Cities and counties with delegated authority must adopt equal or more stringent standards (W.S. 35-9-121). The council''s IFC standards also cover fire prevention in all existing buildings (W.S. 35-9-106(a)(i)(B)).', 'Rules of the Council on Fire Prevention and Electrical Safety in Buildings, Ch. 1 §2(a); W.S. 35-9-106(a)', 'https://wsfm.wyo.gov/', null, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:WY:imc:2024')::uuid, 'WY', md5('academykb:source:imc-2024')::uuid, 'adopts', null, 'International Mechanical Code, 2024 Edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State-adopted minimum fire/building standards. The state fire marshal applies them through plan review of state and local government buildings, larger public buildings, assembly occupancies, child care centers and fuel dispensing facilities (W.S. 35-9-108(a)). Cities and counties with delegated authority must adopt equal or more stringent standards (W.S. 35-9-121).', 'Rules of the Council on Fire Prevention and Electrical Safety in Buildings, Ch. 1 §2(a); W.S. 35-9-106(a)', 'https://wsfm.wyo.gov/', null, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:WY:ifgc:2024')::uuid, 'WY', md5('academykb:source:ifgc-2024')::uuid, 'adopts', null, 'International Fuel Gas Code, 2024 Edition. Commercial and other non-residential buildings. Applies statewide. Local amendments are allowed. State-adopted minimum fire/building standards. The state fire marshal applies them through plan review of state and local government buildings, larger public buildings, assembly occupancies, child care centers and fuel dispensing facilities (W.S. 35-9-108(a)). Cities and counties with delegated authority must adopt equal or more stringent standards (W.S. 35-9-121).', 'Rules of the Council on Fire Prevention and Electrical Safety in Buildings, Ch. 1 §2(a); W.S. 35-9-106(a)', 'https://wsfm.wyo.gov/', null, null, true, '{}'::text[], 'pending_review', null, 'Evidence is not from an official government page.'),
  (md5('academykb:adoption:st:WY:nec:2026')::uuid, 'WY', md5('academykb:source:nec-2026')::uuid, 'adopts', null, 'National Electrical Code (Wyoming Department of Fire Prevention and Electrical Safety). Applies statewide. W.S. 35-9-120(a) makes electrical installations in or on buildings, mobile homes and premises subject to the NEC''s minimum requirements. Local jurisdictions may enforce with certified inspectors (W.S. 35-9-121). The 2026 edition comes from the agency''s adopted-codes list; no rule text or effective date for it was found.', 'W.S. 35-9-120(a)', 'https://wsfm.wyo.gov/electrical-safety/rules-statutes-and-jurisdictions', null, null, true, '{}'::text[], 'verified', '2026-11-22T02:26:12Z'::timestamptz, null)
insert into public.academy_kb_verifications (target_type, target_id, checked_at, method, result, source_url, content_hash, evidence, notes) values
  ('adoption', (md5('academykb:adoption:st:AK:ibc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.020&secEnd=13.50.020', 'b4ee43258ec880d982201f9ea45567861b0a781a9b3b04536432f08ca137d795', '13 AAC 50.020. International Building Code. The International Building Code 2021 Edition (IBC), Chapters 1 - 12, 14 - 28, and 30 - 35, and Appendix C are adopted by reference to regulate all occupancies and buildings', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:iebc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.021&secEnd=13.50.021', '8ce0c5cdc815951c936539b00e99035d4c7aab8733abe0db1bdda701a1f9f9d5', '13 AAC 50.021. International Existing Building Code. The International Existing Building Code 2021 Edition (IEBC), Chapters l - 16, and Appendix A - C, are adopted by reference to regulate all occupancies and buildings', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.023&secEnd=13.50.023', '50d905b39cc72ea0d9b97673fe355fcc86f5c30cee5879fe3df15d2e1d09d4f2', '13 AAC 50.023. International Mechanical Code. The International Mechanical Code 2021 Edition (IMC), Chapters 1 - 15 and Appendix A, are adopted by reference to regulate all occupancies and buildings', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:ifgc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.024&secEnd=13.50.024', '72caab4de5d219490375916b7150dc38f82fa5d5dff99be1d19bb99bf15545fd', '13 AAC 50.024. International Fuel Gas Code. The International Fuel Gas Code 2021 Edition (IFGC), Chapter 3 Section 304 and Chapters 6 and 7, are adopted by reference to regulate the installation of fuel gas utilization equipment, gaseous hydrogen systems, and related accessories', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:ifc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.025&secEnd=13.50.025', '9b6bef10bab619b51ddd4a98ebc39bfddd9739fe603256e2901d2fae277f1385', '13 AAC 50.025. International Fire Code. The International Fire Code 2021 Edition (IFC), Chapters 13 - 19, 41 - 49, and 68 - 79 are reserved. The International Fire Code 2021 Edition (IFC), Chapters 1 - 12, 20 - 40, 50 - 67, and 80 and Appendices B - I, K, L, and N are adopted by reference to regulate all occupancies and buildings', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:nec:2020')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=8.70.025&secEnd=8.70.025', '2e3996ad0ae39e778af908984da798580d8e307878e4e6fc19cbec4d584ccb86', '8 AAC 70.025. Minimum electrical standards. (a) The 2020 Edition of NFPA 70, National Electrical Code, issued by the National Fire Protection Association on August 5, 2019, and approved by the American National Standards Institute on August 25, 2019, constitutes the minimum electrical code for the state and is adopted by reference.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AK:upc:2018')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=8.63.010&secEnd=8.63.010', '5dbd4f851fc78955dfacc02c43147c9684384cfc2ecb8a98d4fbb6ecbc44323a', 'The codes set out in this section are adopted in accordance with AS 18.60.705 as the minimum plumbing standards to be followed throughout the state, except as provided under AS 18.60.710 or 18.60.735. The department adopts the following codes by reference that are published by the International Association of Plumbing and Mechanical Officials (IAPMO): (1) Uniform Plumbing Code , 2018 edition', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'AK', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.akleg.gov/basis/aac.asp?media=print&secStart=13.50.020&secEnd=13.50.020', null, 'Exceptions: 1. Detached one-, two-, and three-family dwellings. 2. Multiple single-family dwellings (townhouses) not more than three stories above grade plane in height with a separate means of egress and their accessory structures.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:AL:ibc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(1) The minimum building standard code adopted by the Division of Construction Management is the 2021 International Building Code.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:iebc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(b) 2021 – International Existing Building Code', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:ipc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(c) 2021 - International Plumbing Code', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:ifgc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(d) 2021 – International Fuel Gas Code', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(e) 2021 - International Mechanical Code, with the following exceptions:', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:nec:2020')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(f) 2020 - National Electrical Code (NFPA 70)', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:ashrae_90_1:2013')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/355-12-1-.01', '99e406e4de56ab063e5a91d296f9ba167e2385ee7d55f470856e3c9716b86806', '(h) ANSI/ASHRAE/IES Standard 90.1 – 2013 Energy Standard for Buildings except Low–Rise Residential Buildings with exceptions permitted to:', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:AL:ifc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://admincode.legislature.state.al.us/api/rule/482-2-101-.02', '8f137ab4103a2dc5382322726a64023bd637f509af7d4de50c4c2b67f67960cf', '(1) Except as specifically provided in paragraph (2), the 2021 edition of the International Fire Code® and Appendices B, C, D, E, and M, as promulgated by the International Code Council®, are adopted by reference as a regulation of the State Fire Marshal.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'AL', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dcm.alabama.gov/bldg_code.aspx', null, 'DCM does not have jurisdiction over residential property or commercial property except for hotels/motels and movie theaters.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:AR:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://labor.arkansas.gov/wp-content/uploads/17CARpt.261.pdf', '5471dead47a60242fa91ec6180bfe255a5e20077b079988f69d470bd11f8a2d3', 'The HVACR Licensing Board hereby adopts and incorporates herein the International Mechanical Code, 2021 edition, of the International Code Council, Inc., commonly referred to as the ICC. (b) The International Mechanical Code, 2021, shall be the standard for the conduct of HVACR work.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'AR', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dps.arkansas.gov/emergency-management/adem/state-fire-marshals-office/helpful-links/', null, 'Arkansas Fire Prevention Code 2021, Volume I, II, III Arkansas Fire Prevention Code 2021, Volume I Fire Arkansas Fire Prevention Code 2021, Volume II Building Arkansas Fire Prevention Code 2021, Volume III Residential', 'Statewide code model, re-checked on the official page.'),
  ('jurisdiction', 'AZ', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.azleg.gov/ars/11/00861.htm', null, 'A. In any county that has adopted zoning pursuant to this chapter, the board of supervisors may adopt and enforce, for the unincorporated areas of the county so zoned, a building code and other related codes to regulate the quality, type of material and workmanship of all aspects of construction of buildings or structures, except that the board may authorize that areas zoned rural or unclassified may be exempt from the provisions of the code adopted.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:CA:ibc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 2 California Building Code, Volumes 1 and 2, based on the 2024 International Building Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:irc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 2.5 California Residential Code, based on the 2024 International Residential Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:nec:2023')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 3 California Electrical Code, based on the 2023 National Electrical Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:umc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 4 California Mechanical Code, based on the 2024 Uniform Mechanical Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:upc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 5 California Plumbing Code, based on the 2024 Uniform Plumbing Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:ifc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 9 California Fire Code, based on the 2024 International Fire Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:iebc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.dgs.ca.gov/-/media/Divisions/BSC/05-Resources/Guidebooks/2025-Guide-toTitle-24---6th-Edition.pdf', '955853a2c9726d37a728d5a3bc694f244c280932279717d48cae5612313366f6', '2025 Guide to Title 24: "Part 10 California Existing Building Code, based on the 2024 International Existing Building Code" | BSC Codes page: "The 2025 California Building Standards Code (Cal. Code Regs., Title 24) will be published July 1, 2025, with an effective date of January 1, 2026."', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CA:state_energy:2025-california-energy-code-building-energy-effici')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.energy.ca.gov/programs-and-topics/programs/building-energy-efficiency-standards/2025-building-energy-efficiency', '55a5722e2edbcc2a8bfded8ff792e0f2f4b2ba63e33af69d7d3f1c1191490a57', 'Buildings whose permit applications are applied for on or after January 1, 2026, must comply with the 2025 Energy Code.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CO:nec:2026')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.sos.state.co.us/CCR/GenerateRulePdf.do?ruleVersionId=12714&fileName=3%20CCR%20710-1', '44721f9ab741854f528959b2daee171a087f3e9fcd9a61543e22dde631196bfa', 'A. The Board hereby incorporates by reference the National Fire Protection Association standard number 70, hereafter known as the National Electrical Code, 2026 Edition. These standards are incorporated by reference as the minimum standards governing the planning, laying out, and installing or the making of additions, alterations, and repairs in the installation of wiring apparatus and equipment for electric light, heat, and power in this state. This Rule does not include later amendments to or editions of the National Electrical Code, 2026 Edition. The effective date shall be August 1, 2026.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CO:ipc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.sos.state.co.us/CCR/GenerateRulePdf.do?ruleVersionId=12668&fileName=3%20CCR%20720-1', '1cb44c8ba4348eab14803465ff5295c647fbe42bcaaa092a5a2585969ea2ee0c', '1. Chapter 1, Sections 101.2, 102, 105, 106.1, 106.3, 106.4, 106.5, 106.5.5, 106.6.1, 107, 108.1, 110.3 Chapters 2-13, 15; and Appendices B, C, D, and E of the IPC, 2024 edition promulgated by the International Code Council 1st printing (June 2023). ... Rules 1.2 eff. 08/14/2026.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'CO', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://leg.colorado.gov/sites/default/files/2022a_1362_signed.pdf', null, '(b) A BOARD OF COUNTY COMMISSIONERS THAT HAS ADOPTED AND ENFORCED ONE OR MORE BUILDING CODES, AND THAT UPDATES ONE OR MORE BUILDING CODES ON OR AFTER JULY 1, 2026, SHALL ADOPT AND BEGIN ENFORCING AN ENERGY CODE THAT ACHIEVES EQUIVALENT OR BETTER ENERGY AND CARBON EMISSIONS PERFORMANCE THAN THE MODEL LOW ENERGY AND CARBON CODE DEVELOPED FOR ADOPTION BY THE ENERGY CODE BOARD PURSUANT TO SECTION 24-38.5-401 (6) AT THE SAME TIME OTHER BUILDING CODES ARE UPDATED.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:CT:ibc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', '(Amd) 101.1 Title. The 2021 International Building Code as amended in this section shall be known as the 2021 International Building Code portion of the 2022 Connecticut State Building Code. (Add) 101.1.1 Statutes. Pursuant to sections 29-252a and 29-253 of the Connecticut General Statutes, respectively, this code shall be the building code for all towns, cities and boroughs and all state agencies.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:irc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Exception: Detached one- and two-family dwellings and multiple single-family dwellings (townhouses) not more than three stories above grade plane in height with a separate means of egress, and their accessory structures not more than three stories above grade plane in height, shall comply with the 2021 International Residential Code portion of the 2022 Connecticut State Building Code.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:iebc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Pursuant to section 29-252 of the Connecticut General Statutes the following national model codes, as amended herein, are adopted and shall be known as the 2022 Connecticut State Building Code: 2021 International Building Code 2017 ICC/ANSI A117.1 Accessible and Usable Buildings and Facilities 2021 International Existing Building Code 2021 International Plumbing Code 2021 International Mechanical Code 2021 International Energy Conservation Code 2020 NFPA 70, National Electrical Code, of the National Fire Protection Association Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:ipc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Pursuant to section 29-252 of the Connecticut General Statutes the following national model codes, as amended herein, are adopted and shall be known as the 2022 Connecticut State Building Code: 2021 International Building Code 2017 ICC/ANSI A117.1 Accessible and Usable Buildings and Facilities 2021 International Existing Building Code 2021 International Plumbing Code 2021 International Mechanical Code 2021 International Energy Conservation Code 2020 NFPA 70, National Electrical Code, of the National Fire Protection Association Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Pursuant to section 29-252 of the Connecticut General Statutes the following national model codes, as amended herein, are adopted and shall be known as the 2022 Connecticut State Building Code: 2021 International Building Code 2017 ICC/ANSI A117.1 Accessible and Usable Buildings and Facilities 2021 International Existing Building Code 2021 International Plumbing Code 2021 International Mechanical Code 2021 International Energy Conservation Code 2020 NFPA 70, National Electrical Code, of the National Fire Protection Association Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:iecc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Pursuant to section 29-252 of the Connecticut General Statutes the following national model codes, as amended herein, are adopted and shall be known as the 2022 Connecticut State Building Code: 2021 International Building Code 2017 ICC/ANSI A117.1 Accessible and Usable Buildings and Facilities 2021 International Existing Building Code 2021 International Plumbing Code 2021 International Mechanical Code 2021 International Energy Conservation Code 2020 NFPA 70, National Electrical Code, of the National Fire Protection Association Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:nec:2020')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', '6a4f32eabb8e451fae0b6585f132cfae99930246ae0c25236e7eee1023de018a', 'Pursuant to section 29-252 of the Connecticut General Statutes the following national model codes, as amended herein, are adopted and shall be known as the 2022 Connecticut State Building Code: 2021 International Building Code 2017 ICC/ANSI A117.1 Accessible and Usable Buildings and Facilities 2021 International Existing Building Code 2021 International Plumbing Code 2021 International Mechanical Code 2021 International Energy Conservation Code 2020 NFPA 70, National Electrical Code, of the National Fire Protection Association Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:ifc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-fire-marshal/2022-csfsc-integrated-errata-1-41123.pdf?rev=4e07494b39064f0f8e60e69fe8639819', '3800efd5c37496e076c5f78d7e1a91acf0053e6f7d66200b7f86266b558183b9', 'Sec. 102.1 Part III – New construction, renovation, or change of use and new buildings. For those for which a permit was issued on or after January 1, 2006. The following standard is hereby adopted as amended in this code as Part III of the Connecticut State Fire Safety Code: International Fire Code® of the International Code Council, Inc., 2021 edition, except as amended, altered or deleted and by the addition of certain provisions as indicated in this code.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:CT:nfpa1:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-state-codes/2022-csfpc-integrated-errata-1.pdf?rev=cd6886d617da4c788bdfed007acd5b4f', 'fd4ec463f25e51d67ff9ba589282e0051647b7489040775f086aebeb199fae2e', 'NFPA 1, Fire CodeTM of the National Fire Protection Association, (NFPA 1), 2021 edition, with ANNEXES A, C, and F except as amended, altered or deleted and by the addition of certain provisions as indicated in Section 1.0.2 of this Code.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'CT', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://portal.ct.gov/das/-/media/das-beta/pdf/office-of-state-building-inspector/2022-csbc-final.pdf?rev=6b86ccc456024731b3eb61ef0b1c71e1', null, '(Add) 101.1.1 Statutes. Pursuant to sections 29-252a and 29-253 of the Connecticut General Statutes, respectively, this code shall be the building code for all towns, cities and boroughs and all state agencies.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:DC:ibc:2015')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dob.dc.gov/node/1613981', '949c930335b09464c7ec6ff46751d4f0719ce131bb95978b28aacfc8db9f9717', 'The 2017 DC Construction Codes consist of the 2015 International Code Council (ICC) family of model codes, the 2014 National Electrical Code, and 2013 ASHRAE 90.1, as amended by the District of Columbia Municipal Regulations (DCMR) Title 12, Sections A through M. The 2017 DC Construction Code takes effect on May 29, 2020.', 'Quote re-checked word for word on the official page by the Academy source check.'),
