  ('adoption', (md5('academykb:adoption:st:ME:iebc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C004.pdf', 'fbb93bf184528768d5a333f2122709fb07ab67ffb5f32707fb4bfb559b391aa0', '1. IEBC. “IEBC” means the 2021 International Existing Building code, published by the International Code Council, Inc.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:ME:iecc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C006_0.pdf', '69990df4b54f4743d2d41971691fd6ba9bc1b763d9cb75f20fa1e91720470ce8', '1. The 2021 International Energy Conservation Code, published by the International Code Council, Inc., is hereby adopted and incorporated by reference.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:ME:ashrae_90_1:2019')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/MUBEC%20Standards%20and%20Amendments.pdf', 'cd68a4f42aeed9990f884b2a344f9817dd806b145221dea13171fca81052a543', '2019 ASHRAE 90.1 (Energy Standard for Buildings except Low-Rise Residential Buildings) editions without addenda.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:ME:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.maine.gov/dps/fmo/sites/maine.gov.dps.fmo/files/inline-files/642C007.pdf', 'd100e6b6f01a4131afa58a052aa23e0a20d6d296b0e9e9a5f11489806feb6a2a', '4. IMC. “IMC” means the International Mechanical Code, published by the International Code Council, Inc., 2021 edition (adopted as part of the MUBEC).', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:ME:nec:2026')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.maine.gov/pfr/professionallicensing/professions/electricians', '549669330ac9e60c292b6e4d0cb51b80ad42f796ab95ca1b43d3e86a00d5cbd8', 'All installations of electrical equipment commencing on or after July 1, 2026 must comply with the NFPA standard 70, National Electrical Code (2026 edition), Copyright © 2025 National Fire Protection Association as adopted by the Board', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'ME', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://legislature.maine.gov/statutes/10/title10sec9724.html', null, 'This chapter provides express limitations on municipal home rule authority. The Maine Uniform Building and Energy Code must be enforced in a municipality that has more than 4,000 residents. The Maine Uniform Building and Energy Code must be enforced through inspections that comply with Title 25, section 2373 .', 'Statewide code model, re-checked on the official page.'),
