  ('jurisdiction', 'NM', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.srca.nm.gov/parts/title14/14.005.0001.html', null, 'Authority having jurisdiction AHJ means the state or a municipality, county or other political subdivision that has a full-service building department employing a full-time certified building official and has permitting, inspection and enforcement authority over the general construction, electrical and mechanical-plumbing trades within its jurisdiction.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:NV:iecc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://www.energy.nv.gov/programs/building-energy-codes/state-adoption-status/', '17092048f1e40c9c39b8e316fd9b343fda50e7352716bbd69b2208592fb81d56', 'GOE has adopted the 2024 IECC as published effective August 18, 2024 by reference pursuant to NAC 701.185 as adopted by LCB file R153-17.', 'Quote re-checked word for word on the official page by the Academy source check.'),
