  ('adoption', (md5('academykb:adoption:st:NY:iecc:2024')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dos.ny.gov/notice-adoption', 'fc352e7b98435c42c24107525a8ba22bbd335f823cdc44c09e64ba3d7cd5ad9d', 'Effective Date: The effective date of the modifications to Part 1240 is December 31, 2025. There is no transition period. Beginning on December 31, 2025, regulated parties submitting building permit applications will be required to comply with the 2025 ECCCNYS and NYS ASHRAE 90.1-2025.', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:NY:ashrae_90_1:2022')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dos.ny.gov/system/files/documents/2025/03/full-regulatory-impact-statement-energy-code.pdf', '9f15b29dd6a0d70904687fc0db07e5c9fce80b586879a80837b37477cdd41610', 'ASHRAE 90.1-2022 is the most recently published ASHRAE 90.1 and the 2024 NYS ASHRAE 90.1 is based on ASHRAE 90.1-2022', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'NY', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://dos.ny.gov/code/local-government-state-agency-enforcement-programs', null, 'Title 19 NYCRR Part 1203 requires every city, village, town, and county, charged with administration and enforcement of the NYS Uniform Fire Prevention and Building Code (Uniform Code) to annually submit a report of its activities to the Secretary of State.', 'Statewide code model, re-checked on the official page.'),
  ('adoption', (md5('academykb:adoption:st:OH:ibc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:1-1-01', '028a904b6a22e647eb5cf95ca681c27df410046ae8d2abb18471b1b70211681a', '101.1 Incorporation by reference, title and rules of construction. Except as provided in Chapters 4101:1-1 to 4101:1-35 of the Administrative Code, the International Building Code 2021 edition, Chapters 2 through 35 and appendix H', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:OH:state_residential:2018')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:8-1-01', 'ee6df687e735b069d13069a157c268fbbb3809da8d1f850bc104befcf7e98f0f', 'The 2018 edition of the “International Residential Code”, first printing, Chapters 2 through 24, 29, and 44 as published by the “International Code Council, Inc.” is used as the basis of this document', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:OH:imc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:2-1-01', '4ca87423ae71a128ac0624e74c0bda4b3de14dd1fdbb946a16285a6d253218aa', 'Except as provided in Chapters 4101:2-1 to 4101:2-15 of the Administrative Code, the International Mechanical Code 2021 edition, Chapters 2 through 10 and Chapters 12 through 15, and the International Mechanical Code 2024 edition, Chapter 11,', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:OH:ipc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/ohio-administrative-code/rule-4101:3-1-01', '3f72e3dcb84908276a34bc8bf580a43072db0896b113979f55a0c758acd4aeed', 'Except as provided in Chapters 4101:3-1 to 4101:3-15 of the Administrative Code, the International Plumbing Code, 2021 edition, Chapters 2 through 15', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:OH:iecc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/1/4101$1-35-01_eff_10_15_25.pdf', 'b9a3d6a20d12419c2bb7b4fb8c18d81285867be244746f780ba7758eb78d766d', 'IECC - 21 International Energy Conservation Code (adoption includes Chapters 2 through 6 of 4101:1-35-01 3 both the commercial provisions and the residential provisions, and as further modified in Chapter 13 of this code)', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('adoption', (md5('academykb:adoption:st:OH:ashrae_90_1:2019')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/1/4101$1-35-01_eff_10_15_25.pdf', 'b9a3d6a20d12419c2bb7b4fb8c18d81285867be244746f780ba7758eb78d766d', 'ASHRAE Standard Referenced Title 90.1-19 Energy Standard for Buildings Except Low- rise Residential Buildings.', 'Quote re-checked word for word on the official page by the Academy source check.'),
