  ('adoption', (md5('academykb:adoption:st:OH:ifc:2021')::uuid)::text, '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/ohio-administrative-code/rule-1301:7-7-01', '3995181b7e1f2e98280f760a6d38424ad29d3881cb22f0321b359ab9a63ef8cf', 'Except as otherwise specified in Ohio Administrative Code Chapters 1301:7-7-01 through 1301:7-7-80, Chapters 1 through 11 and 20 through 80 of the 2021 edition of the International Fire Code and Chapter 12 of the 2024 edition of the International Fire Code', 'Quote re-checked word for word on the official page by the Academy source check.'),
  ('jurisdiction', 'OH', '2026-11-22T02:26:12Z'::timestamptz, 'official_text', 'verified', 'https://codes.ohio.gov/assets/laws/administrative-code/rules/4101/8/4101$8-1-01_eff_7_1_19.pdf', null, '101.5 Jurisdiction without a certified residential building department. If no municipal, township, or county building department is certified by the Board of Building Standards for residential buildings in accordance with section 3781.10(E) of the Revised Code has jurisdiction, the owner is not required to make submission of construction documents, seek approvals, request inspections, or obtain certificates of occupancy required in this Chapter.', 'Statewide code model, re-checked on the official page.'),
